// Issues #4, #6: only call WMS inventory for Vinculum merchants;
// when no wmsCode selected, fall back to pinCode inventory (consistent with checkout)
boolean isVinculumItem = ["Vinculum"].contains(cartInstance?.offer?.merchant?.activeWMS) &&
        cartInstance?.offer?.merchant?.warehouseLocationCode
if(wmsCode && isVinculumItem){
    def inventory = lakshyaAssociateOfferService.getInventoryForWarehouse(webSite, cartInstance?.offer, wmsCode)
    int inventoryQty = inventory ? inventory.qty : 0
    if(inventoryQty <= 0){
        itemDTO.setOutOfStock(true)
        anyItemOOS = true
        itemDTO.setWmsMessage("Product is not available at this warehouse.")
    }
    itemDTO.setMaximumOrderQty(inventoryQty)
}else if(isVinculumItem){
    def inventory = lakshyaAssociateOfferService.getInventory(webSite, pinCode, cartInstance?.offer)
    int inventoryQty = inventory ? inventory.qty : 0
    if(inventoryQty <= 0){
        itemDTO.setOutOfStock(true)
        anyItemOOS = true
    }
    itemDTO.setMaximumOrderQty(inventoryQty)
}else{
    itemDTO.setMaximumOrderQty(cartInstance.offer.qty)
}

