							userCouponDTO.setDiscountType(userCouponObj.coupon.promotion.discountType.toString())
							if(userCouponObj?.coupon?.promotion.promotionType == PromotionTypeEnum.AUTO || userCouponObj?.coupon?.promotion.promotionType == PromotionTypeEnum.PREORDER || userCouponObj?.coupon?.promotion.promotionType==PromotionTypeEnum.RULES){
