		boolean isHeroProductActive = false

		rsts.each{
			index++
			minimumOrderQty = userCartService.getMinimumOrderQty(it)
			orderMultiples = userCartService.getOrderMultiples(it)
			if(!itemQuantityFlag){
				itemQuantityFlag = userCartService.isCartQuantityValid(it, cartId);
			}

			try {
