					chargeMap.name = message(code: 'mobile.tax.title')
					chargeMap.key = "Tax"
					allCharges << chargeMap
			}
			def deliveryCharges = wholeSaleResult["deliveryCharges"]
			if (deliveryCharges) {
				chargeMap = [:]
				chargeMap.value = Utils.setDecimalFormat(deliveryCharges)
				chargeMap.name = message(code: 'delivery.charges.title')
				chargeMap.key = "Delivery Charge"
				allCharges << chargeMap
			}

			def wholesaleGrandTotal = wholeSaleResult["grandTotal"]
			def firstOrderCoupon = wholeSaleResult["usrFirstOrderDiscount"]
			def userCouponList = wholeSaleResult["userCouponList"]
			def chequeBounceCharge = wholeSaleResult["chequeBounceCharge"]
