							}
							promoCode = userCoupon?.coupon?.couponCode
							//wholesaleGrandTotal = wholeSaleResult["grandTotal"] - discount
						}
					}

					usrCpnLstMap = [:]
					usrCpnLstMap["promotionId"] = ucpn.coupon?.promotion?.id
					usrCpnLstMap["discountAmount"] = ucpn.discountAmount
					usrCpnLstMap["couponStatus"] = ucpn.couponStatus.name()
					usrCpnLstMap["applyMode"] = ucpn.coupon?.promotion?.applyMode.name()
					usrCpnLstMap["discountType"] = ucpn?.coupon?.promotion?.discountType?.name()
					usrCpnLstMap["couponCode"] = ucpn.coupon?.promotion?.couponCode
					usrCpnLstMap["promotionName"] = ucpn.coupon?.promotion?.promotionName
					usrCpnLstMap["freeQuantity"] = null
					if(ucpn?.coupon?.promotion?.additionalQty>0){
						usrCpnLstMap["promotionName"] = message(code:'promo.additionalqty.message', default:"Get Additional {0} qty at zero cost.",args:[ucpn?.coupon?.promotion?.additionalQty])
						usrCpnLstMap["freeQuantity"] = "${ucpn?.coupon?.promotion?.additionalQty} Qty"
						usrCpnLstMap["promotionName"] = "Free Quantity"
						usrCpnLstMap["promotionSubName"] = "(${ucpn.coupon.promotion.promotionName})"
						ucpn.userCartList?.each{ c ->
								cartItemList.each{ cItem ->
									if(cItem?.id?.toString()?.equals(c?.id?.toString())){
										cItem["additionalQtyMessage"] = message(code:"cart.focqty.label", default:"Additional ${ucpn?.coupon?.promotion?.additionalQty} quantity added, as part of promotion. Hurry and complete your purchase before it gets sold out.")
									}
								}
						}
					}
					usrCpnLstMap["promotionType"] = ucpn.coupon?.promotion?.promotionType
					usrCpnLstMap["cashbackFlag"] = cashbackFlag
					usrCpnLstMap["enableRemove"] = enableRemove
					usrCpnLst << usrCpnLstMap
					//println ucpn
				}
			}
			def allDiscount = [:]
			def allDiscounts = []
			//bulkDiscount
			def bulkDiscount = userCartService.calculateBulkQuantityDiscount(cartItems)

			//wrapper for mobile api
			def cartListMap = [:]
			if (cartId) {
				cartListMap['cartId'] = cartId
			}
			cartListMap['basketDiscount'] = basketDiscount
			cartListMap['promoCode'] = promoCode
			if (basketDiscount) {
				allDiscount.name = message(code: 'basket.discount.title')
				allDiscount.value = Utils.setDecimalFormat(basketDiscount)
				allDiscount.key = "Basket Discount"
				allDiscounts << allDiscount
			}

			if (advanceAmount && advanceAmount > 0 && wholesaleGrandTotal > 0) {
				cartListMap['advanceAmount'] = advanceAmount
				wholesaleGrandTotal = wholesaleGrandTotal - advanceAmount
			}
			def walletAmnt = 0
			if (reqParamObj?.redeemedAmount) {
				walletAmnt = reqParamObj?.redeemedAmount
			}
			if (walletAmnt && walletAmnt > 0 && wholesaleGrandTotal > 0) {
				cartListMap['redeemedAmount'] = Utils.setDecimalFormat(walletAmnt)
				wholesaleGrandTotal = wholesaleGrandTotal - walletAmnt
			}

			cartListMap['grandTotal'] = Utils.setDecimalFormat(wholesaleGrandTotal)
			cartListMap.tax = tax ? Utils.setDecimalFormat(tax) : 0
			cartListMap['discount'] = discount
			cartListMap['comboDiscount'] = comboDiscount
			if (comboDiscount) {
				allDiscount = [:]
				allDiscount.name = message(code: 'combo.discount.title')
				allDiscount.value = Utils.setDecimalFormat(comboDiscount)
				allDiscount.key = "Combo Discount"
				allDiscounts << allDiscount
			}
			cartListMap['cashBackDiscount'] = cashBackDiscount
			cartListMap['deliveryCharges'] = deliveryCharges
			cartListMap['subTotal'] = Utils.setScale(wholesaleRowTotal)
			cartListMap['itemQty'] = itemQty
			cartListMap['productCount'] = cartItems.size()
			cartListMap['cartItemList'] = cartItemList
			def activePromotion = promotionService.findApplicablePromotional(usr, WebSite.get(wst),clientId)
			def activePromos = []
			def activePromo = [:]
			cartListMap["coupon"] = activePromos
			cartListMap["promotionText"] = getPromotionText(userCoupon, cartId, basketDiscount)
			cartListMap["totalSaving"] = bulkDiscount
			if (firstOrderCoupon) {
				def firstOrderCouponData = [:]
				allDiscount.firstOrderDiscount = firstOrderCoupon.discountAmount
				firstOrderCouponData["discountAmount"] = firstOrderCoupon.discountAmount
				firstOrderCouponData["couponCode"] = firstOrderCoupon?.firstOrderCoupon?.couponCode
				firstOrderCouponData["promotionName"] = firstOrderCoupon?.firstOrderCoupon?.promotionName
				firstOrderCouponData["firstOrderText"] = "${message(code: 'promotion.firstOrder.label')}"
				cartListMap["firstOrderCoupon"] = firstOrderCouponData

				allDiscount = [:]
				allDiscount.name = "${message(code: 'promotion.firstOrder.label')}" + " (-)"
				allDiscount.value = firstOrderCoupon.discountAmount
				allDiscount.key = "Inaugural Discount"
				allDiscounts << allDiscount
			}

			def loyaltyDiscount = wholeSaleResult["loyaltyDiscount"]
			if (loyaltyDiscount && loyaltyDiscount>0) {
				cartListMap["loyaltyDiscount"] = loyaltyDiscount
				allDiscount.name = "${message(code: 'promotion.loyaltyDiscount.label', default:"Loyalty Discount")}" + " (-)"
				allDiscount.value = loyaltyDiscount
				allDiscount.key = "Loyalty Discount"
				allDiscounts << allDiscount
			}
			cartListMap["allDiscounts"] = allDiscounts
			cartListMap["allCharges"] = allCharges
			def validateCartMap = lakshyaUtilsService.validateCartValue(cartItems, wst, wholesaleGrandTotal, paymentMethod)
			def cartDeliveryChargeMsg = []
			if (validateCartMap) {
				def valCartMap = [:]
				valCartMap["minimumCartFlag"] = validateCartMap["minimumCartFlag"]

				valCartMap["category"] = validateCartMap["category"]
				valCartMap["categories"] = validateCartMap["categories"]
				def cartValMsges = []
				def carvalmsg
				def categoryValListMsg = validateCartMap["categoryList"]

				if (categoryValListMsg) {
					def categorylabel
					categoryValListMsg.each { categoryValMsg ->
						def minimumCartValue = categoryValMsg.minimumCartValue
						def maximumCartValue = categoryValMsg.maximumCartValue
						categorylabel = "title.${categoryValMsg.categoryName}"
						categorylabel = categorylabel?.toLowerCase()
						categorylabel = message(code: categorylabel)
						def catMin = "${categoryValMsg.minMax}"
						if (catMin == 'Min') {
							if (paymentMethod) {
								carvalmsg = message(code: 'shoppingcart.categorycartitem.min.paymentmethod.msg', args: [categorylabel, minimumCartValue, paymentMethod])
							} else {
								carvalmsg = message(code: 'shoppingcart.categorycartitem.min.msg', args: [categorylabel, minimumCartValue])
							}
						} else {
							if (paymentMethod) {
								carvalmsg = message(code: 'shoppingcart.categorycartitem.max.paymentmethod.msg', args: [categorylabel, maximumCartValue, paymentMethod])
							} else {
								carvalmsg = message(code: 'shoppingcart.categorycartitem.max.msg', args: [categorylabel, maximumCartValue])
							}
						}
						cartValMsges << carvalmsg

					}
					valCartMap["validateCartMessage"] = cartValMsges
				}

				if (isAnyOfferExpired) {
					valCartMap["minimumCartFlag"] = isAnyOfferExpired
					if (valCartMap["validateCartMessage"] == null) {
						valCartMap["validateCartMessage"] = []
					}
					valCartMap["validateCartMessage"] << message(code: 'offer.expired.error.msg')
				}
				cartListMap["validateCartMap"] = valCartMap
				cartListMap["restrictedBrandValue"] = validateCartMap.restrictedBrandValue
				cartListMap["productBrand"] = validateCartMap.productBrand
			}
			if (deliveryCharges && wholeSaleResult?.deliveryChargeUptoAmount && wholeSaleResult?.surchargeAmount) {
				cartDeliveryChargeMsg << message(code: 'cart.delivery.charge.msg', args: [wholeSaleResult["deliveryChargeUptoAmount"], wholeSaleResult["surchargeAmount"]])
				cartListMap["cartDeliveryChargeMsg"] = cartDeliveryChargeMsg
			}
			cartListMap["userCouponList"] = usrCpnLst
			if (chequeBounceCharge) {
				cartListMap["chequeBounceCharge"] = chequeBounceCharge
				cartListMap["chequeBounceChargeMsg"] = message(code: 'cheque.bounce.charge.msg')
			}
			cartListMap.categoryType = categoryType
			cartListMap.isAdvanceAmountApplicable = isAdvanceAmountApplicable
			cartListMap.outOfStock = outOfStockAtCart
			if (cartListMap.subTotal) {
				cartListMap.subTotal = Utils.setDecimalFormat(cartListMap.subTotal)
			}
			cartListMap["canApplyPromoCodes"] = true;
			if(preorderId){
				cartListMap["preOrderId"] = preorderId;
				cartListMap["canModifyCartItems"] = lakshyaUtilsService.preorderQuantityRestriction();
				cartListMap["canApplyPromoCodes"] = false;
			}
			cartListMap

		} else {
			return null
		}
	}
	def private getPromotionText(def userCoupon, def cartId, def basketDiscount) {
		def proText = ""
		if (cartId) {
			proText = "${message(code: 'yoursuggestedbasket.content')} ${message(code: 'yoursuggestedbasket.contenthigh')} ${basketDiscount}"
			if (userCoupon && (userCoupon?.coupon?.promotion.promotionType == PromotionTypeEnum.AUTO || userCoupon?.coupon?.promotion.promotionType == PromotionTypeEnum.RULES)) {
				if (PromotionDiscountTypeEnum.FIXED_CASHBACK == userCoupon?.coupon?.promotion?.discountType || PromotionDiscountTypeEnum.RELATIVE_CASHBACK == userCoupon?.coupon?.promotion?.discountType) {
					proText = "${proText} ${message(code: 'specialPromotionCartcashback.messsage.suggested')}"
				} else {
					proText = "${proText} ${message(code: 'specialPromotionCartDiscount.messsage.first')}"
				}
				proText = "${proText} ${userCoupon.discountAmount} ${message(code: 'specialPromotionCartDiscount.messsage.second')} ${userCoupon?.coupon?.promotion?.description}"
			}
		} else {
			if (userCoupon && (userCoupon?.coupon?.promotion.promotionType == PromotionTypeEnum.AUTO || userCoupon?.coupon?.promotion.promotionType == PromotionTypeEnum.RULES)) {
				proText = message(code: 'yoursuggestedbasket.content')

				if (PromotionDiscountTypeEnum.FIXED_CASHBACK == userCoupon?.coupon?.promotion?.discountType || PromotionDiscountTypeEnum.RELATIVE_CASHBACK == userCoupon?.coupon?.promotion?.discountType) {
					proText = "${proText} ${message(code: 'specialPromotionCartcashback.messsage.first')}"
				} else {
					proText = "${proText} ${message(code: 'specialPromotionCartDiscount.messsage.first')}"
				}
				proText = "${proText} ${userCoupon.discountAmount}  ${message(code: 'specialPromotionCartDiscount.messsage.second')} ${userCoupon?.coupon?.promotion?.description}"
			}
		}
		return proText
	}
	private def setOfferVal(def offer, def offerN) {
		if (offer) {
			offerN["id"] = offer.id
			def preorderId = offerN["preorderId"]
			offerN["estimatedDeliveryDays"] = offer.estimatedDeliveryDays
			if (offer?.estimatedDeliveryDays) {
				offerN.estimatedDeliveryDate = getEstimatedDeliveryDate(offer?.estimatedDeliveryDays)
			} else {
				offerN.estimatedDeliveryDate = getEstimatedDeliveryDate(0)
			}
			offerN["groupBuyingMinimumLimit"] = offer.groupBuyingMinimumLimit
			offerN["tierPricing"] = offer.tierPricing
			offerN["couponCode"] = offer.couponCode
			offerN["couponSaving"] = offer.couponSaving
			offerN["estimatedDeliveryDays"] = offer.estimatedDeliveryDays
			offerN["groupBuyingMinimumLimit"] = offer.groupBuyingMinimumLimit
			offerN["groupBuyingPrice"] = offer.groupBuyingPrice
			def merch = offer.merchant.refresh()
			offerN["merchant"] = merch
			offerN["minimumOrderQty"] = offer.minimumOrderQty
			if (!offer.minimumOrderQty) {
				offerN["minimumOrderQty"] = merch.minimumOrderQty
			}
			offerN["multiples"] = offer.multiples
			if (!offer.multiples) {
				offerN["multiples"] = merch.multiples
			}
			offerN["offerPrice"] = offer.offerPrice
			offerN["processingDays"] = offer.processingDays
			def pd = offer.product.refresh()
			def tempImages
			def wst = request['x-website-id'].toString()
			String mediaurl = servletContext.configuration."${wst}".'mob_web_media_url'
			if (pd) {
				tempImages = []
				for (def image : pd.images) {
					if (image.width == 200 || image.width == 500) {
						image.source = Utils.awsImagePath(offer.product.id?.toString(), image.angle, mediaurl, image.width + "")
						//"${servletContext.configuration."${wst}".'web_media_url'}${awsPath}/${fname}_${image.angle}_200.jpg"
					} else if (image.width == 0) {
						image.source = Utils.awsImagePath(offer.product.id?.toString(), image.angle, mediaurl, "orig")
						//"${servletContext.configuration."${wst}".'web_media_url'}${awsPath}/${fname}_${image.angle}_orig.jpg"
					}
					tempImages << image
				}
			}
			pd.images = null
			pd.images = tempImages
			offerN["product"] = pd
			offerN["productLead"] = offer.productLead
			offerN["qty"] = offer.qty
			offerN["qtyInCart"] = offer.qtyInCart
			offerN["regularPrice"] = offer.regularPrice
			offerN["sku"] = offer.sku
			offerN.pricingGroups = offer.pricingGroups
			offerN.outofStockQty = offer.outofStockQty
			offerN.partNumber = offer?.product?.attributes?.sellerskuid
			offerN.stockType = offer?.product?.attributes?.stocktype
			offerN["inventoryQty"] = offer.qty
			if(preorderId != null){
				offerN["inventoryvalidation"] = "You have reached the maximum quantity available as a part of this offer"
			}
			else {
				offerN["inventoryvalidation"] = message(code: 'inventory.validation.message', args: [offer.qty])
			}

			def currentDate = new Date()
			if (offer.validTill < currentDate || !offer.active) {
				offerN["isOfferExpired"] = true
			} else {
				offerN["isOfferExpired"] = false
			}
		}
	}
	def getEstimatedDeliveryDate(def esitmatedDelDate) {
		return new Date() + esitmatedDelDate
	}
	def addSuggestedProduct(){

		def cartId = params.cartId
		if (params.id){
			def cartItem = userCartService.addBackSuggestedOffer(params.id)
			if (cartItem){
				String msgCode = "${cartItem?.offer?.product?.attributes?.name}"
				if(cartItem?.offer?.stockType){
					msgCode = "${cartItem?.offer?.product?.attributes?.name} - " + cartItem?.offer.stockType + (cartItem?.offer.stockDate ? "( "+ cartItem?.offer.stockDate+" )" : "" )
				}
				flash.message = message(code: 'lakshyacart.productupdatedshoppingcart.label')+ msgCode + message(code: 'lakshyacart.producthasupdated.label')
			} else {
				flash.error = message(code: 'lakshyacart.productremovedalreadyremoved.label')
			}

			if (request.xhr){
				render "added"
				return
			}else{
				chain(controller:"lakshyaCart",action: "index",id:cartId)
				return
			}
		}
	}

	@Override
	def remove(){
		Map paramMap = params
		def cartId = params.cartId
		if (params.id){
			// params.id is the merchant product offer
			def cartItem = UserCart.get(params.id)
			def statusFlag = cartItem ? userCartService.removeCartInstance(cartItem, request['x-website-id'].toString(), cartId,PromotionPlatformEnum.WEB) : false

			if (statusFlag){
				String msgCode = "${cartItem?.offer?.product?.attributes?.name}"
				if(cartItem?.offer?.stockType){
					msgCode = "${cartItem?.offer?.product?.attributes?.name} - " + cartItem?.offer.stockType + (cartItem?.offer.stockDate ? "( "+ cartItem?.offer.stockDate+" )" : "" )
				}
				flash.message = message(code: 'lakshyacart.productupdatedshoppingcart.label')+ ' ' + msgCode+ ' '+message(code: 'lakshyacart.productremoved.label')
			} else {
				flash.error = message(code: 'lakshyacart.productremovedalreadyremoved.label')
			}

			if (request.xhr){
				render "Removed"
				return
			}else{
				if(!params.actionPage){
					chain(controller:"lakshyaCart",action: "index",id: cartId)
				}else{
					chain(controller:"lakshyaCheckout",action: "preview",id: params.addressId,params:paramMap)
				}
				return
			}
		}
	}

	@Secured("ROLE_USER")
	def removeCart() {
		Map paramMap 		= params
		def cartId 			= params.cartId
		def usr 			= springSecurityService.isLoggedIn() ? springSecurityService.currentUser : null
		def addressId 		= params.addressId
		def sess 			= session.getId().toString()
		def webSite 		= request['x-website-id'] ? request['x-website-id'].toString() : null
		def web_media_url	= servletContext.configuration."${webSite}"."web_media_url"
		def address 	    = UserAddress.findByUserAndId(usr,addressId)
		def pinCode 	    = address?.pinCode
		def marketplace = session["clientId"] ? session["clientId"]?.toString() : null
		CartDTO cartDTO = new CartDTO()
		try{
				if (params.id){
					// params.id is the merchant product offer
					def cartItem = UserCart.get(params.id)
					def statusFlag = cartItem ? userCartService.removeCartInstance(cartItem, webSite, cartId, PromotionPlatformEnum.WEB) : false
					if (statusFlag) {
						def rsts = userCartService.getUserCartList(usr, webSite, sess, cartId,true,marketplace)
						def cartList 		= []
						def quantity		= 0
						boolean anyItemOOS  = false
						def preorderId = null;
						rsts.each { cartInstance ->
							CartItemDTO itemDTO = new CartItemDTO()
							//LIPLWEB-7016
							if(cartInstance.offerUpdated){
								itemDTO.setOfferUpdated(true)
							}
							if(cartInstance.preorderId){
								preorderId = cartInstance.preorderId;
							}
							itemDTO.setCanModifyCartItems(cartInstance.canModifyCartItems ? cartInstance.canModifyCartItems : true);
							if(preorderId){
								itemDTO.setPreOrderId(preorderId);
								itemDTO.setCanModifyCartItems(lakshyaUtilsService.preorderQuantityRestriction());
							}
							def minimumOrderQty = userCartService.getMinimumOrderQty(cartInstance)
							def orderMultiples = userCartService.getOrderMultiples(cartInstance)

							itemDTO.setId(cartInstance.id.toString())
							itemDTO.setQuantity(cartInstance.qty)
							itemDTO.setProductName(cartInstance.offer.product.attributes.modelname)
							itemDTO.setProductNumber(cartInstance.offer.product.attributes.modelnumber)
							itemDTO.setMasterCategory(cartInstance.offer.product.attributes.mastercategory)
							itemDTO.setProductCategory(cartInstance.offer.product.attributes.productcategory)
							itemDTO.setSubCategory(cartInstance.offer.product.attributes.subcategory)
							itemDTO.setCategory(cartInstance.offer.product.attributes.category)
							itemDTO.setSellerSKUId(cartInstance.offer.product.attributes.sellerskuid)
                            itemDTO.setBrand(cartInstance.offer.product.attributes.brand)
							itemDTO.setMoq(minimumOrderQty)
							itemDTO.setMultiple(orderMultiples)
							itemDTO.setServiceable(true)
							if(pinCode){
								def serviceableAddress = merchantServiceabilityService.checkAvailability(cartInstance.offer.merchant, pinCode)
								if(!serviceableAddress){
									itemDTO.setServiceable(false)
								}
							}

							if (cartInstance.offer.qty <= 0) {
								itemDTO.setOutOfStock(true)
								anyItemOOS = true
							} else if(cartInstance.offer.validTill < new Date()){
								itemDTO.setOutOfStock(true)
								anyItemOOS = true
							} else {
								if(!cartInstance.offer.active || !cartInstance.offer.product.active ){
									anyItemOOS = true
									itemDTO.setOutOfStock(true)
								}else{
									itemDTO.setOutOfStock(false)
								}
							}

							if(cartInstance.qty > cartInstance.offer.qty){
								anyItemOOS = true
							}

							if(cartInstance.offer.productLead){
								itemDTO.setPrivateOffer(true)
								//LIPLWEB-7016
								itemDTO.setOfferDeadline(cartInstance?.offer?.validTill?.getTime())
							}
							itemDTO.setStockDate(cartInstance.offer.stockDate)
							itemDTO.setStockType(cartInstance.offer.stockType)
							itemDTO.setCartValue(cartInstance.offer.offerPrice)
							itemDTO.setCartTotalValue(cartInstance.offer.offerPrice * cartInstance.qty)
							itemDTO.setTierPricing(cartInstance?.offer?.tierPricing?cartInstance.offer.tierPricing:[])
							if(["Vinculum"].contains(cartInstance?.offer?.merchant?.activeWMS) && cartInstance?.offer?.merchant?.warehouseLocationCode){
                                def inventory = lakshyaAssociateOfferService.getInventory(webSite, pinCode, cartInstance?.offer)
                                int inventoryQty = inventory ? inventory.qty : 0
                                itemDTO.setMaximumOrderQty(inventoryQty)
                            }else{
                                itemDTO.setMaximumOrderQty(cartInstance.offer.qty)
                            }

							def fname = cartInstance.offer.product.id.toString()
							def awsPath = fname[0] + "/" + fname[1] + "/" + fname[2] + "/" + fname[3]
							def productImage = web_media_url + "/" + awsPath + "/" + fname + "_FRONT_200.jpg"

							itemDTO.setProductImageUrl(productImage)
							itemDTO.setProductPageUrl("")
							itemDTO.setProductId(cartInstance.offer.product.id.toString())
							quantity += cartInstance.qty
							try{
								if(cartInstance?.buyerExpectedDeliveryDate){
									SimpleDateFormat sourceFormat = new SimpleDateFormat("MM/dd/yyyy")
									def date = sourceFormat.format(cartInstance?.buyerExpectedDeliveryDate)
									itemDTO.setBuyerExpectedDeliveryDate(date)
								}
							}catch(Exception e){
								e.printStackTrace()
							}
							cartList << itemDTO
						}

						cartDTO.setCartItems(cartList)
						cartDTO.setTotalProduct(cartList.size())
						cartDTO.setTotalQuantity(quantity)
						cartDTO.setAnyItemOutOfStock(anyItemOOS)

						def wholeSaleData = userCartService.deduceCartData(usr, webSite, rsts, cartId, PromotionPlatformEnum.WEB)
						def comboDiscount = wholeSaleData["comboDiscount"]
						def wholesaleRowTotal = wholeSaleData["total"]
						def deliveryCharges = wholeSaleData["deliveryCharges"]
						def wholesaleGrandTotal = wholeSaleData["grandTotal"]
						def bulkDiscount = wholeSaleData["bulkDiscount"]
						def basketDiscount = wholeSaleData["basketDiscount"]
						def basketCount = wholeSaleData["basketCount"]
						def firstOrderDiscount = wholeSaleData["usrFirstOrderDiscount"]
						def userCouponList = wholeSaleData["userCouponList"]
						def chequeBounceCharge = wholeSaleData["chequeBounceCharge"]
						def deliveryChargesText = wholeSaleData["deliveryChargesText"]
						def tax = wholeSaleData["tax"]
						def cashBackAmount = wholeSaleData["cashBackAmount"]
						def userCashBackCouponList = wholeSaleData["userCashBackCouponList"]

						// payment summary
						PaymentSummaryDTO summaryData = new PaymentSummaryDTO()

						if(userCashBackCouponList){
							def userCashBackCouponDTOList = []
							if(userCashBackCouponList && userCashBackCouponList.size()>0){
								userCashBackCouponList.each{userCouponObj ->
									UserCouponDTO userCouponDTO = new UserCouponDTO()
									userCouponDTO.setId(userCouponObj.id.toString())
									userCouponDTO.setCouponCode(userCouponObj.coupon.couponCode)
									userCouponDTO.setDiscount(userCouponObj.discountAmount)
									userCouponDTO.setCouponName(userCouponObj.coupon.promotion.promotionName)
									userCouponDTO.setMinimumOrderValue(userCouponObj.coupon.promotion.minmumOrderValue)
									userCouponDTO.setDiscountValue(userCouponObj.coupon.promotion.value)
									userCouponDTO.setDiscountType(userCouponObj.coupon.promotion.discountType.toString())
									if(userCouponObj?.coupon?.promotion.promotionType == PromotionTypeEnum.AUTO || userCouponObj?.coupon?.promotion.promotionType == PromotionTypeEnum.PREORDER || userCouponObj?.coupon?.promotion.promotionType==PromotionTypeEnum.RULES){
										userCouponDTO.setRemovable(false)
									}else{
										userCouponDTO.setRemovable(true)
									}

									userCouponDTO.setCashBackPromotion(true)
									userCashBackCouponDTOList << userCouponDTO
								}
								summaryData.setUserCashBackCoupon(userCashBackCouponDTOList)
							}
						}

						if(cashBackAmount){
							summaryData.setTotalCashBackAmount(cashBackAmount)
						}
                        if(wholesaleGrandTotal){
                            summaryData.setGrandTotal(wholesaleGrandTotal)
                        }

                        if(tax){
                            summaryData.setTax(tax)
                        }

                        if(wholesaleRowTotal){
                            summaryData.setSubTotal(wholesaleRowTotal)
                        }

                        if(deliveryCharges){
                            summaryData.setDeliveryCharge(deliveryCharges)
                        }

                        if(comboDiscount){
                            summaryData.setComboDiscount(comboDiscount)
                        }

                        if(bulkDiscount){
                            summaryData.setBulkDiscount(bulkDiscount)
                        }

                        if(basketDiscount){
                            summaryData.setBasketDiscount(basketDiscount)
                        }

                        if(chequeBounceCharge){
                            summaryData.setChequeBounceCharge(chequeBounceCharge)
                        }

						//summaryData.setDeliveryChargesText(deliveryChargesText)
                        if(basketCount){
                            summaryData.setBasketCount(basketCount)
                        }

						//user coupon list
						def userCouponDTOList = []
						if (userCouponList && userCouponList.size() > 0) {
							userCouponList.each { userCouponObj ->
								UserCouponDTO userCouponDTO = new UserCouponDTO()
								userCouponDTO.setId(userCouponObj.id.toString())
								userCouponDTO.setCouponCode(userCouponObj.coupon.couponCode)
								userCouponDTO.setDiscount(userCouponObj.discountAmount)
								userCouponDTO.setCouponName(userCouponObj.coupon.promotion.promotionName)
								userCouponDTO.setDescription(userCouponObj.coupon.promotion.description)
								userCouponDTO.setMinimumOrderValue(userCouponObj.coupon.promotion.minmumOrderValue)
								userCouponDTO.setDiscountValue(userCouponObj.coupon.promotion.value)
								userCouponDTO.setDiscountType(userCouponObj.coupon.promotion.discountType.toString())
								if(userCouponObj?.coupon?.promotion.promotionType == PromotionTypeEnum.AUTO || userCouponObj?.coupon?.promotion.promotionType == PromotionTypeEnum.PREORDER || userCouponObj?.coupon?.promotion.promotionType==PromotionTypeEnum.RULES){
									userCouponDTO.setRemovable(false)
								}else{
									userCouponDTO.setRemovable(true)
								}

								if(PromotionDiscountTypeEnum.FIXED_CASHBACK== userCouponObj?.coupon?.promotion?.discountType || PromotionDiscountTypeEnum.RELATIVE_CASHBACK== userCouponObj?.coupon?.promotion?.discountType) {
									userCouponDTO.setCashBackPromotion(true)
								}
								userCouponDTOList << userCouponDTO
							}
							summaryData.setUserCoupon(userCouponDTOList)
						}

						// first order discount
						if (firstOrderDiscount) {
							UserCouponDTO firstOrderPromo = new UserCouponDTO()
							firstOrderPromo.setId(firstOrderDiscount.id.toString())
							firstOrderPromo.setCouponCode(firstOrderDiscount.firstOrderCoupon.couponCode)
							firstOrderPromo.setDiscount(firstOrderDiscount.discountAmount)
							firstOrderPromo.setCouponName(firstOrderDiscount.firstOrderCoupon.promotionName)
							firstOrderPromo.setDescription(firstOrderDiscount.firstOrderCoupon.description)
							firstOrderPromo.setMinimumOrderValue(firstOrderDiscount.firstOrderCoupon.minmumOrderValue)
							firstOrderPromo.setDiscountValue(firstOrderDiscount.firstOrderCoupon.discountValue)
							firstOrderPromo.setDiscountType(firstOrderDiscount.firstOrderCoupon.discountType.toString())
							firstOrderPromo.setRemovable(false)
							firstOrderPromo.setCashBackPromotion(false)
							summaryData.setFirstOrderCoupon(firstOrderPromo)
						}

						cartDTO.setPaymentSummary(summaryData)
						try{
							def assisted = session['AssistAgent'] ? true : false
							if(cartId){
								asyncAbandonCartService.updateAbandonedCart(usr,rsts,true,assisted)
							}else{
								asyncAbandonCartService.updateAbandonedCart(usr,rsts,false, assisted)
							}
						}catch(Exception e){
							log.error ("Exception occured while updating abandoned cart details", e)
							e.printStackTrace()
						}
					}
					cartDTO.setMinCartValue(userCartService.getMinimumCartValueForUser(usr,webSite))
					cartDTO.setStatusCode(HttpStatus.OK.value().toString())

					String product = "${cartItem?.offer?.product?.attributes?.name}"
					if(cartItem?.offer?.stockType){
						product = "${cartItem?.offer?.product?.attributes?.name} - " + cartItem?.offer.stockType + (cartItem?.offer.stockDate ? "( "+ cartItem?.offer.stockDate+" )" : "" )
					}
					String message = message(code: 'lakshyacart.productupdatedshoppingcart.label')+ ' ' + product+ ' '+message(code: 'lakshyacart.productremoved.label')

					//cartDTO.setMessage("Cart Removed")
					cartDTO.setMessage(message)
				} else {
					cartDTO.setStatus(false)
					cartDTO.setMessage("CartId is wrong")
				}
		}catch(Exception e) {
			cartDTO.setStatusCode(HttpStatus.INTERNAL_SERVER_ERROR.value().toString())
			cartDTO.setMessage("Error in removing the cart")
			log.error("Error in removing the cart {}",e)
		}
		render cartDTO as JSON
	}

	@Override
	def update(UserCart userCartInstance){

		def cartId = params.cartId
		def actionPage = params.actionPage
		log.info request.getHeader('referer')

		if (userCartInstance == null) {
			flash.error = message(code: 'lakshyacart.notfound.label')
			return
		}

		if (userCartInstance.hasErrors()) {
			if(!actionPage){
				chain (controller:"lakshyaCart",action:"index",id: cartId,model:userCartInstance.errors)
			}else{
				chain(controller:"lakshyaCheckout",action: "preview",id: params.addressId,model:userCartInstance.errors,params:[cartId:cartId])
			}
			return
		}

		userCartService.updateCart(userCartInstance, request['x-website-id'].toString());

		if (request.xhr){
			render "Updated"
			return
		}else{
			flash.message = message(code: 'lakshyacart.cartupdated.label')
			if(!actionPage){
				chain(controller:"lakshyaCart",action: "index",id: cartId)
			}else{
				chain(controller:"lakshyaCheckout",action: "preview",id: params.addressId,params:[cartId:cartId])
			}
			return
		}

	}

	@Secured("ROLE_USER")
	def updateCart(){
		def usr 			= springSecurityService.isLoggedIn() ? springSecurityService.currentUser : null
		def cartId 			= params.cartId
		def addressId 		= params.addressId
		def sess 			= session.getId().toString()
		def webSite 		= request['x-website-id'] ? request['x-website-id'].toString() : null
		def web_media_url 	= servletContext.configuration."${webSite}"."web_media_url"
		boolean isString 	= (params.id instanceof String)
		def address 	    = UserAddress.findByUserAndId(usr,addressId)
		def pinCode 	    = address?.pinCode
		CartDTO cartDTO 	= new CartDTO()
		def rsts
		def marketplace = session["clientId"] ? session["clientId"]?.toString() : null
		try{
			if(params.id){
				userCartService.updateBulkCart(params,isString,webSite)
				cartDTO.setMessage(message(code: 'lakshyacart.cartupdated.label'))
			}
			rsts = userCartService.getUserCartList(usr, webSite, sess, cartId,true,marketplace)
			def cartList = []
			def quantity = 0
			boolean anyItemOOS = false
			def preorderId = null;
			rsts.each { cartInstance ->
				CartItemDTO itemDTO = new CartItemDTO()
				//LIPLWEB-7100 LIPLWEB-7016
				if(cartInstance.offerUpdated){
					itemDTO.setOfferUpdated(true)
				}
				if(cartInstance.preorderId){
					preorderId = cartInstance.preorderId;
				}
				itemDTO.setCanModifyCartItems(cartInstance.canModifyCartItems ? cartInstance.canModifyCartItems : true);
				if(preorderId){
					itemDTO.setPreOrderId(preorderId);
					itemDTO.setCanModifyCartItems(lakshyaUtilsService.preorderQuantityRestriction());
				}
				def minimumOrderQty = userCartService.getMinimumOrderQty(cartInstance)
				def orderMultiples 	= userCartService.getOrderMultiples(cartInstance)

				itemDTO.setId(cartInstance.id.toString())
				itemDTO.setQuantity(cartInstance.qty)
				itemDTO.setProductName(cartInstance.offer.product.attributes.modelname)
				itemDTO.setProductNumber(cartInstance.offer.product.attributes.modelnumber)
				itemDTO.setMasterCategory(cartInstance.offer.product.attributes.mastercategory)
				itemDTO.setProductCategory(cartInstance.offer.product.attributes.productcategory)
				itemDTO.setSubCategory(cartInstance.offer.product.attributes.subcategory)
				itemDTO.setCategory(cartInstance.offer.product.attributes.category)
				itemDTO.setSellerSKUId(cartInstance.offer.product.attributes.sellerskuid)
                itemDTO.setBrand(cartInstance.offer.product.attributes.brand)
				itemDTO.setMoq(minimumOrderQty)
				itemDTO.setMultiple(orderMultiples)

				itemDTO.setServiceable(true)
				if(pinCode){
					def serviceableAddress = merchantServiceabilityService.checkAvailability(cartInstance.offer.merchant, pinCode)
					if(!serviceableAddress){
						itemDTO.setServiceable(false)
					}
				}


				if(cartInstance.offer.qty <= 0){
					itemDTO.setOutOfStock(true)
					anyItemOOS = true
				}else if(cartInstance.offer.validTill < new Date()){
					itemDTO.setOutOfStock(true)
					anyItemOOS = true
				}else{
					if(!cartInstance.offer.active || !cartInstance.offer.product.active ){
						anyItemOOS = true
						itemDTO.setOutOfStock(true)
					}else{
						itemDTO.setOutOfStock(false)
					}
				}

				if(cartInstance.qty > cartInstance.offer.qty){
					anyItemOOS = true
				}

				if(cartInstance.offer.productLead){
					itemDTO.setPrivateOffer(true)
				}
				itemDTO.setStockDate(cartInstance.offer.stockDate)
				itemDTO.setStockType(cartInstance.offer.stockType)
				itemDTO.setCartValue(cartInstance.offer.offerPrice)
				itemDTO.setCartTotalValue(cartInstance.offer.offerPrice * cartInstance.qty)
				itemDTO.setTierPricing(cartInstance.offer.tierPricing?cartInstance.offer.tierPricing:[])
				if(["Vinculum"].contains(cartInstance?.offer?.merchant?.activeWMS) && cartInstance?.offer?.merchant?.warehouseLocationCode){
                    def inventory = lakshyaAssociateOfferService.getInventory(webSite, pinCode, cartInstance?.offer)
                    int inventoryQty = inventory ? inventory.qty : 0
                    if(inventoryQty <= 0){
                        itemDTO.setOutOfStock(true)
                        anyItemOOS = true
                    }
                    itemDTO.setMaximumOrderQty(inventoryQty)
                }else{
                    itemDTO.setMaximumOrderQty(cartInstance.offer.qty)
                }

				def fname 			= cartInstance.offer.product.id.toString()
				def awsPath 		= fname[0]+"/"+fname[1]+"/"+fname[2]+"/"+fname[3]
				def productImage	= web_media_url+"/"+awsPath+"/"+fname+"_FRONT_200.jpg"

				itemDTO.setProductImageUrl(productImage)
				itemDTO.setProductPageUrl("")
				itemDTO.setProductId(cartInstance.offer.product.id.toString())
				quantity +=cartInstance.qty
				try{
					if(cartInstance?.buyerExpectedDeliveryDate){
						SimpleDateFormat sourceFormat = new SimpleDateFormat("MM/dd/yyyy")
						def date = sourceFormat.format(cartInstance?.buyerExpectedDeliveryDate)
						itemDTO.setBuyerExpectedDeliveryDate(date)
					}
				}catch(Exception e){
					e.printStackTrace()
				}
				cartList << itemDTO
			}

			cartDTO.setCartItems(cartList)
			cartDTO.setTotalProduct(cartList.size())
			cartDTO.setTotalQuantity(quantity)
			cartDTO.setAnyItemOutOfStock(anyItemOOS)

			def mp = session["marketplace"] ? session["marketplace"]?.toString() : null
			def dataMap=[:]
			def assistAgent = session['AssistAgent'] ? session['AssistAgent'] : null
			def isPromotionApplicable = true
			if(assistAgent){
				isPromotionApplicable = promotionService.isPromotionAllow(assistAgent)
			}
			dataMap.isPromotionApplicable = isPromotionApplicable
			def wholeSaleData 		= userCartService.deduceCartData(usr, webSite,rsts,cartId,PromotionPlatformEnum.WEB,usr.defaultPinCode,false,mp,dataMap)
			def check = false
			wholeSaleData["userCouponList"]?.each{ userCouponObj ->
				def addQty = userCouponObj?.coupon?.promotion?.additionalQty
				if(userCouponObj?.coupon?.promotion?.additionalQty>0){
					userCouponObj.userCartList?.each{ c ->
						cartList.each{ cItem ->
							if(cItem?.id?.equals(c?.id?.toString())){
								def p = [:]
								p.id = c?.id?.toString();
								p.qty = (c.qty + addQty);
								//c.qty = (c.qty + addQty);
								cItem.setAdditionalQty(addQty)
								//cItem.setQuantity(p.qty)//userCartService.updateBulkCart(p,true,webSite)
								cItem.setPromotionName(userCouponObj?.coupon?.promotion?.promotionName)
								check = true
							}
						}
					}
				}
			}

			def comboDiscount 		= wholeSaleData["comboDiscount"]
			def wholesaleRowTotal 	= wholeSaleData["total"]
			def deliveryCharges 	= wholeSaleData["deliveryCharges"]
			def wholesaleGrandTotal = wholeSaleData["grandTotal"]
			def bulkDiscount 		= wholeSaleData["bulkDiscount"]
			def basketDiscount 		= wholeSaleData["basketDiscount"]
			def basketCount 		= wholeSaleData["basketCount"]
			def firstOrderDiscount 	= wholeSaleData["usrFirstOrderDiscount"]
			def userCouponList 		= wholeSaleData["userCouponList"]
			def chequeBounceCharge 	= wholeSaleData["chequeBounceCharge"]
			def deliveryChargesText = wholeSaleData["deliveryChargesText"]
			def tax 				= wholeSaleData["tax"]
			def cashBackAmount		= wholeSaleData["cashBackAmount"]
			def userCashBackCouponList  = wholeSaleData["userCashBackCouponList"]
			def loyaltyDiscount  = wholeSaleData["loyaltyDiscount"]

			// payment summary
			PaymentSummaryDTO summaryData = new PaymentSummaryDTO()

			if(userCashBackCouponList){

				if(userCashBackCouponList){
					def userCashBackCouponDTOList = []
					if(userCashBackCouponList && userCashBackCouponList.size()>0){
						userCashBackCouponList.each{userCouponObj ->
							UserCouponDTO userCouponDTO = new UserCouponDTO()
							userCouponDTO.setId(userCouponObj.id.toString())
							userCouponDTO.setCouponCode(userCouponObj.coupon.couponCode)
							userCouponDTO.setDiscount(userCouponObj.discountAmount)
							userCouponDTO.setCouponName(userCouponObj.coupon.promotion.promotionName)
							userCouponDTO.setMinimumOrderValue(userCouponObj.coupon.promotion.minmumOrderValue)
							userCouponDTO.setDiscountValue(userCouponObj.coupon.promotion.value)
							userCouponDTO.setDiscountType(userCouponObj.coupon.promotion.discountType.toString())
							if(userCouponObj?.coupon?.promotion.promotionType == PromotionTypeEnum.AUTO || userCouponObj?.coupon?.promotion.promotionType == PromotionTypeEnum.PREORDER || userCouponObj?.coupon?.promotion.promotionType==PromotionTypeEnum.RULES){
								userCouponDTO.setRemovable(false)
							}else{
								userCouponDTO.setRemovable(true)
							}

							userCouponDTO.setCashBackPromotion(true)
							userCashBackCouponDTOList << userCouponDTO
						}
						summaryData.setUserCashBackCoupon(userCashBackCouponDTOList)
					}

				}
			}

			if(cashBackAmount){
				summaryData.setTotalCashBackAmount(cashBackAmount)
			}

            if(wholesaleGrandTotal){
                summaryData.setGrandTotal(wholesaleGrandTotal)
            }

            if(tax){
                summaryData.setTax(tax)
            }

            if(wholesaleRowTotal){
                summaryData.setSubTotal(wholesaleRowTotal)
            }

            if(deliveryCharges){
                summaryData.setDeliveryCharge(deliveryCharges)
            }

            if(comboDiscount){
                summaryData.setComboDiscount(comboDiscount)
            }

            if(bulkDiscount){
                summaryData.setBulkDiscount(bulkDiscount)
            }

            if(basketDiscount){
                summaryData.setBasketDiscount(basketDiscount)
            }

            if(chequeBounceCharge){
                summaryData.setChequeBounceCharge(chequeBounceCharge)
            }

            //summaryData.setDeliveryChargesText(deliveryChargesText)
            if(basketCount){
                summaryData.setBasketCount(basketCount)
            }

			//user coupon list
			def userCouponDTOList = []
			if(userCouponList && userCouponList.size()>0){
				userCouponList.each{userCouponObj ->
					UserCouponDTO userCouponDTO = new UserCouponDTO()
					userCouponDTO.setId(userCouponObj.id.toString())
					userCouponDTO.setCouponCode(userCouponObj.coupon.couponCode)
					userCouponDTO.setDiscount(userCouponObj.discountAmount)
					userCouponDTO.setCouponName(userCouponObj.coupon.promotion.promotionName)
					userCouponDTO.setDescription(userCouponObj.coupon.promotion.description)
					userCouponDTO.setMinimumOrderValue(userCouponObj.coupon.promotion.minmumOrderValue)
					userCouponDTO.setDiscountValue(userCouponObj.coupon.promotion.value)
					userCouponDTO.setDiscountType(userCouponObj.coupon.promotion.discountType.toString())
					if(userCouponObj?.coupon?.promotion.promotionType == PromotionTypeEnum.AUTO || userCouponObj?.coupon?.promotion.promotionType == PromotionTypeEnum.PREORDER || userCouponObj?.coupon?.promotion.promotionType==PromotionTypeEnum.RULES){
						userCouponDTO.setRemovable(false)
					}else{
						userCouponDTO.setRemovable(true)
					}

					if(PromotionDiscountTypeEnum.FIXED_CASHBACK== userCouponObj?.coupon?.promotion?.discountType || PromotionDiscountTypeEnum.RELATIVE_CASHBACK== userCouponObj?.coupon?.promotion?.discountType) {
						userCouponDTO.setCashBackPromotion(true)
					}
					if(userCouponObj?.coupon?.promotion?.additionalQty>0){
						userCouponDTO.setDiscount(0)
						userCouponDTO.setCouponName("Free Quantity")
						userCouponDTO.setCouponPromoText("(${userCouponObj.coupon.promotion.promotionName})")
						userCouponDTO.setAdditionalQty(userCouponObj?.coupon?.promotion?.additionalQty)
					}
					userCouponDTOList << userCouponDTO
				}
				summaryData.setUserCoupon(userCouponDTOList)
			}

			// first order discount
			if(firstOrderDiscount){
				UserCouponDTO firstOrderPromo = new UserCouponDTO()
				firstOrderPromo.setId(firstOrderDiscount.id.toString())
				firstOrderPromo.setCouponCode(firstOrderDiscount.firstOrderCoupon.couponCode)
				firstOrderPromo.setDiscount(firstOrderDiscount.discountAmount)
				firstOrderPromo.setCouponName(firstOrderDiscount.firstOrderCoupon.promotionName)
				firstOrderPromo.setDescription(firstOrderDiscount.firstOrderCoupon.description)
				firstOrderPromo.setMinimumOrderValue(firstOrderDiscount.firstOrderCoupon.minmumOrderValue)
				firstOrderPromo.setDiscountValue(firstOrderDiscount.firstOrderCoupon.discountValue)
				firstOrderPromo.setDiscountType(firstOrderDiscount.firstOrderCoupon.discountType.toString())
				firstOrderPromo.setRemovable(false)
				firstOrderPromo.setCashBackPromotion(false)
				summaryData.setFirstOrderCoupon(firstOrderPromo)
			}
			if(loyaltyDiscount){
				summaryData.setLoyaltyDiscount(loyaltyDiscount)
			}
			cartDTO.setPaymentSummary(summaryData)
			cartDTO.setMinCartValue(userCartService.getMinimumCartValueForUser(usr,webSite))
			cartDTO.setStatusCode(HttpStatus.OK.toString())
			//cartDTO.setMessage("Cart Updated")
			cartDTO.setMessage(message(code: 'lakshyacart.cartupdated.label'))
			try{
				def assisted = session['AssistAgent'] ? true : false
				if(cartId){
					asyncAbandonCartService.updateAbandonedCart(usr,rsts,true,assisted)
				}else{
					asyncAbandonCartService.updateAbandonedCart(usr,rsts,false,assisted)
				}
			}catch(Exception e){
				log.error("Some error occured while updating the cart",e)
				e.printStackTrace()
			}
		}catch(Exception e){
			cartDTO.setStatusCode(HttpStatus.INTERNAL_SERVER_ERROR.toString())
			cartDTO.setMessage("error in updating the cart")
			log.error("error in updating the cart {}",e)
		}

		render cartDTO as JSON
	}

	def updateBulk(){
		Map paramMap = params
		def cartId = paramMap?.cartId
		def actionPage = paramMap?.actionPage
		boolean isString = (paramMap?.id instanceof String)
		def addressId = paramMap.addressId

		if(paramMap?.id){
			userCartService.updateBulkCart(paramMap,isString,request['x-website-id'].toString());
			flash.message = message(code: 'lakshyacart.cartupdated.label')
		}

		if(!actionPage){
			chain(controller:"lakshyaCart",action: "index",id: cartId)
		}
		else{
			chain(controller:"lakshyaCheckout",action: "checkPreview",id: addressId,params:paramMap)
		}
	}

	@Override
	@Secured(['ROLE_USER', 'ROLE_ADMIN', 'ROLE_MERCHANT'])
	def carttowishlist(){

		def cartId = params.cartId
		if (params.id){
			// ID of the cart item, not product
			def usr = springSecurityService.isLoggedIn() ? springSecurityService.currentUser : null
			def wst = request['x-website-id'].toString()
			def sess = session.getId().toString()
			def cartItem = UserCart.get(params.id)
			if (cartItem){
				def prod = cartItem.offer.product
				if (UserWishlist.findByUserAndProduct(usr,prod)){
					String msgCode = "${cartItem?.offer?.product?.attributes?.name}"
					if(cartItem?.offer?.stockType){
						msgCode = "${cartItem?.offer?.product?.attributes?.name} - " + cartItem?.offer.stockType + (cartItem?.offer.stockDate ? "( "+ cartItem?.offer.stockDate+" )" : "" )
					}
					flash.alert = message(code: 'lakshyacart.productupdatedshoppingcart.label')+ msgCode+ message(code: 'lakshyacart.alreadyinwishlist.label')
					userCartService.deleteCartItem(cartItem, wst);
					if(!params.actionPage){
						chain(controller:"lakshyaCart",action: "index",id: cartId)
					}else{
						chain(controller:"lakshyaCheckout",action: "preview",id: params.addressId,params:[cartId:cartId])
					}
					return
				}else {
					if (UserWishlist.countByUser(usr) < 100){
						userCartService.saveToWishlist(usr,prod,request['x-website-id'].toString())
						userCartService.deleteCartItem(cartItem, wst);
						flash.message = message(code: 'lakshyacart.productupdatedshoppingcart.label')+ "${prod?.attributes?.name}"+ message(code: 'lakshyacart.movedtowishlist.label')+ "<strong><span class=\"glyphicon glyphicon-heart\" aria-hidden=\"true\"></span> ${link(controller:'account',action:'wishlist') { 'My Wishlist' } }</strong>"
						if(!params.actionPage){
							chain(controller:"lakshyaCart",action: "index",id: cartId)
						}else{
							chain(controller:"lakshyaCheckout",action: "preview",id: params.addressId,params:[cartId:cartId])
						}
						return
					}else{
						flash.error = message(code: 'lakshyacart.wishlistfull.label')
						if(!params.actionPage){
							chain(controller:"lakshyaCart",action: "index",id: cartId)
						}else{
							chain(controller:"lakshyaCheckout",action: "preview",id: params.addressId,params:[cartId:cartId])
						}
						return
					}
				}
			}
		}
		chain(controller:"lakshyaCart", action: "index", id: cartId)
		return

	}
