				}

				if (it.offer.cpt){
					cpt << g.render(template:"cartitem", model:[cartItemInstance:it , minimumOrderQty:minimumOrderQty, orderMultiples:orderMultiples,cartId:cartId])
				}

				if (it.offer.group){
