							if (paymentMethod) {
								carvalmsg = message(code: 'shoppingcart.categorycartitem.max.paymentmethod.msg', args: [categorylabel, maximumCartValue, paymentMethod])
							} else {
								carvalmsg = message(code: 'shoppingcart.categorycartitem.max.msg', args: [categorylabel, maximumCartValue])
