	}

	@Override
	def update(UserCart userCartInstance){

		def cartId = params.cartId
		def actionPage = params.actionPage
		log.info request.getHeader('referer')

		if (userCartInstance == null) {
			flash.error = message(code: 'lakshyacart.notfound.label')
			return
		}

		if (userCartInstance.hasErrors()) {
			if(!actionPage){
				chain (controller:"lakshyaCart",action:"index",id: cartId,model:userCartInstance.errors)
			}else{
				chain(controller:"lakshyaCheckout",action: "preview",id: params.addressId,model:userCartInstance.errors,params:[cartId:cartId])
			}
			return
		}

		userCartService.updateCart(userCartInstance, request['x-website-id'].toString());

		if (request.xhr){
			render "Updated"
			return
		}else{
			flash.message = message(code: 'lakshyacart.cartupdated.label')
			if(!actionPage){
				chain(controller:"lakshyaCart",action: "index",id: cartId)
			}else{
				chain(controller:"lakshyaCheckout",action: "preview",id: params.addressId,params:[cartId:cartId])
			}
			return
		}

	}

