	@Secured(['ROLE_USER'])
	def expressCheckout() {
		def cartId = request.JSON.cartId
		def wst = request['x-website-id'].toString()
		def usr = springSecurityService.isLoggedIn() ? springSecurityService.currentUser : null
		def userMobile = session['userMobile'] ? session['userMobile'] : null
		if(userMobile){
			usr= User.findByMobile(userMobile)
		}
		def data = new Data()
		def clientId = session["clientId"]?.toString() ? session["clientId"]?.toString() : null
		if (cartId && cartId.equals("e1")) {
			userCartService.deleteUserCart(usr, wst, cartId)
			def offerId = request.JSON.offerId
			def qty = request.JSON.qty
			def pinCode = request.JSON.pinCode
			def comboId = request.JSON.comboId
			def offerIds = request.JSON.offerIds
			Map paramObj = request.JSON
			if(clientId){
				paramObj.clientId = clientId
			}
			if (comboId && !offerIds) {
				SuggestedCombo combo = SuggestedCombo.get(comboId)
				combo.offers.each { ofr ->
					request.JSON.qty = null
					paramObj.id = ofr.id
					data = addToNormalCart(paramObj)
					offerId = ofr.id
				}
			} else if (!comboId && offerIds) {
				offerIds.each { ofrid ->
					paramObj.id = ofrid
					data = addToNormalCart(paramObj)
					offerId = ofrid
				}
			} else {
				paramObj.id = offerId
				data = addToNormalCart(paramObj)
			}
			def serviceableAddress = anyAddressIsServiceable(wst, usr, offerId)
			if (serviceableAddress && data.data) {
				data.data["isItServiceableAddress"] = serviceableAddress["isItServiceableAddress"]
				data.data["serviceableAddressId"] = serviceableAddress["serviceableAddressId"]
			}
			respond data
			// @sarthak added clickedBuyNow event
			if (data.getStatuscode() == 200)
				notify('clickedBuyNow', ['Data'    : data, 'user': usr, 'quantity': qty, 'webSite': request['x-website-id'].toString(),
										 'platform': 'APP'])
			return
		} else {
			data.errors << "valid cartId is mandatory"
			data.setStatusCode(HttpStatus.BAD_REQUEST)
			respond data
			return
		}

	}
	def anyAddressIsServiceable(def wst, def usr, def offerId) {
		def addresses = UserAddressExtension.findAllByUserAndWebSite(usr, WebSite.get(wst))
		def seraddress = [:]
		if (!addresses) {
			seraddress["isItServiceableAddress"] = false
			return seraddress
		}
		def merchantProductOffer = MerchantProductOffer.get(offerId)
		boolean serviceable = false
		def serviceableAddressId
		if (merchantProductOffer) {
			addresses.each { adrs ->
				if (!serviceable) {
					serviceable = merchantServiceabilityService.checkAvailability(merchantProductOffer.merchant, adrs.pinCode)
					serviceableAddressId = adrs?.id
				}
			}
		}
		seraddress["isItServiceableAddress"] = serviceable
		if (serviceable) {
			seraddress["serviceableAddressId"] = serviceableAddressId
		}
		return seraddress
	}
