    @Secured(['ROLE_USER'])
    def deleteUserAddress(params) {

        def usr = springSecurityService.isLoggedIn() ? springSecurityService.currentUser : null

        AddressDTO resultDTO = new AddressDTO()

        try {
            resultDTO.setUserId(usr.id.toString())
            resultDTO.setMobile(usr.mobile)
            resultDTO.setFullName(usr.fullName)

            def address = UserAddress.findByUserAndId(usr, params['id'])
            if (address) {
                address.delete(flush: true)
                resultDTO.setStatusCode(HttpStatus.OK.toString())
                resultDTO.setMessage(message(code: 'account.removedaddress.label'))
            } else {
                resultDTO.setStatusCode(HttpStatus.BAD_REQUEST.toString())
                resultDTO.setMessage("Address not found")
            }
        } catch (Exception e) {
            log.error("error in deleting the address {}", e)
            resultDTO.setStatusCode(HttpStatus.INTERNAL_SERVER_ERROR.toString())
            resultDTO.setMessage("error in fetching the address")
        }

        render resultDTO as JSON
    }

