        } catch (Exception e) {
            log.error("edit address {}", e)
            responseData["message"] = "error in fetching the address"
            responseData["statusCode"] = HttpStatus.INTERNAL_SERVER_ERROR.toString()
        }

        render responseData as JSON
    }

