                return;
            }*/
            if (UserAddressExtension.findByGstinAndUserNotEqual(gstin, usr)) {
                resultDTO.setStatusCode(HttpStatus.BAD_REQUEST.value().toString());
                resultDTO.setMessage(message(code: 'gstin.duplicate.error', default: 'Duplicate Gstin'));
                render resultDTO as JSON;
                return;
            }

            def gstinValidationEnabled = appConfigParamService.enableGstinValidation(webSite);
            if (gstinValidationEnabled) {
                def response = genericGstinService.validateGstin(webSite, gstin)
                if (response.isSuccess() == false) {
                    resultDTO.setStatusCode(HttpStatus.BAD_REQUEST.value().toString());
                    def infoMessage = response.getMessage() ? response.getMessage() : message(code: 'gstin.invalid.error', default: 'Invalid Gstin')
                    resultDTO.setMessage(infoMessage);
                    render resultDTO as JSON;
                    return;
                }
                if (response?.isSuccess() == true) {
                    if (!userAddressDTO.getState().toString().trim().equalsIgnoreCase(response.getState().toString().trim()) || !userAddressDTO.getCompany().toString().trim().equalsIgnoreCase(response.getBusinessName().trim())) {
                        resultDTO.setStatusCode(HttpStatus.BAD_REQUEST.value().toString());
                        def message = message(code: 'gstin.firmname.state.mismatch.error', default: 'Gstin state/firmname and entered state/firmname do not match.')
                        resultDTO.setMessage(message);
                        render resultDTO as JSON;
                        return;
                    }
                }
            }
        }

        try {
            def userFullname = userAddressDTO.getFullName();
            if (userFullname) {
                if (userFullname.length() > 50) {
                    resultDTO.setStatusCode(HttpStatus.BAD_REQUEST.value().toString());
                    resultDTO.setMessage(message(code: 'user.name.size.error'));
                    render resultDTO as JSON;
                    return;
                } else if (!userFullname.matches(Utils.getNameRegex())) {
                    resultDTO.setStatusCode(HttpStatus.BAD_REQUEST.value().toString());
                    resultDTO.setMessage(message(code: 'user.name.pattern.error'));
                    render resultDTO as JSON;
                    return;
                }
            }

            def companyName = userAddressDTO.getCompany();
            if (companyName) {
                if (!userAddressDTO.getGstin()) {
                    if (companyName.length() > 100) {
                        resultDTO.setStatusCode(HttpStatus.BAD_REQUEST.value().toString());
                        resultDTO.setMessage(message(code: 'user.company.size.error'));
                        render resultDTO as JSON;
                        return;
                    } else if (!companyName.matches(Utils.getFirmNameRegex())) {
                        resultDTO.setStatusCode(HttpStatus.BAD_REQUEST.value().toString());
                        resultDTO.setMessage(message(code: 'user.company.pattern.error'));
                        render resultDTO as JSON;
                        return;
                    }
                }
            }

            if (!usr.fullName) {
                def name = StringUtils.split(userAddressDTO.getFullName(), " ", 2)
                usr.firstName = name[0]
                if (name.size() > 1) {
                    usr.lastName = name[1]
                }
                usr.fullName = userAddressDTO.getFullName()
                isUserCahange = true
            }

            if (!locationService.validateLocationMapping(userAddressDTO.getPinCode(), userAddressDTO.getCity(), userAddressDTO.getState())) {
                resultDTO.setStatusCode(HttpStatus.BAD_REQUEST.value().toString());
                resultDTO.setMessage(message(code: 'location.mismatch', default: 'Pincode/City/State Mismatch.'));
                render resultDTO as JSON;
                return;
            }

            userAddressInstance.fullName = userAddressDTO.getFullName()
            userAddressInstance.company = userAddressDTO.getCompany()
            userAddressInstance.firstName = usr.firstName
            userAddressInstance.lastName = usr.lastName
            userAddressInstance.addressLine1 = userAddressDTO.getAddressLine()
            userAddressInstance.addressLine2 = userAddressDTO.getAddressLine2()
            userAddressInstance.city = userAddressDTO.getCity()
            userAddressInstance.state = userAddressDTO.getState()
            userAddressInstance.pinCode = userAddressDTO.getPinCode()
            userAddressInstance.phone = usr.mobile
            userAddressInstance.landmark = userAddressDTO.getLandmark()
            userAddressInstance.area = userAddressDTO.getArea()
            userAddressInstance.defaultAddress = userAddressDTO.getDefaultAddress()
            userAddressInstance.selectedAddress = userAddressDTO.getSelected()
            userAddressInstance.otherArea = userAddressDTO.getOtherArea()
            userAddressInstance.gstin = userAddressDTO.getGstin()
            userAddressInstance.webSite = WebSite.get(webSite)
            userAddressInstance.country = CountryCodesEnum.IN

            if (userAddressCount == 0) {
                userAddressInstance.setDefaultAddress(true)
            }

            if (!usr.company) {
                usr.company = userAddressInstance.company
                isUserCahange = true
            }

            if (!usr.gstin && userAddressInstance.gstin) {
                usr.gstin = userAddressInstance.gstin
                usr.company = userAddressInstance.company
                isUserCahange = true
            }

            //existing default address
            if (userAddressDTO.getDefaultAddress()) {
                UserAddressExtension oldDefaultAddress = UserAddressExtension.createCriteria().get {
                    eq('defaultAddress', true)
                    if (userAddressDTO.getId()) {
                        ne('_id', userAddressInstance.id)
                    }

                    eq('user', usr)
                }
                //If a default address is already set
                if (oldDefaultAddress) {
                    oldDefaultAddress.defaultAddress = false
                    oldDefaultAddress.save(flush: true)
                }
                usr.defaultPinCode = userAddressInstance.pinCode
                isUserCahange = true

            }
            if (isUserCahange) {
                usr.save(flush: true)
            }

            userAddressInstance.save(failOnError: true, flush: true)

            resultDTO.setStatusCode(HttpStatus.OK.value().toString())
            if (userAddressDTO.getId()) {
                resultDTO.setMessage("Address updated successfully")
            } else {
                resultDTO.setMessage("Address added successfully")
            }


        } catch (Exception e) {
            log.error("error in adding the address {}", e)
            resultDTO.setStatusCode(HttpStatus.INTERNAL_SERVER_ERROR.value().toString())
            resultDTO.setMessage("error in adding the address")
        }

        render resultDTO as JSON
    }

    @Secured(['ROLE_USER'])
    def address(params) {

        def usr = springSecurityService.isLoggedIn() ? springSecurityService.currentUser : null
        def webSite = request['x-website-id'] ? request['x-website-id'].toString() : null


        AddressDTO resultDTO = new AddressDTO()

