            addresses.each { address ->
                UserAddressDTO addressDTO = new UserAddressDTO()
                addressDTO.setId(address.id.toString())
                addressDTO.setCompany(Utils.removeControlCharacters(address.gstin?address.company:usr.company?usr.company:""))
                addressDTO.setFirstName(Utils.removeControlCharacters(address.firstName))
                addressDTO.setLastName(Utils.removeControlCharacters(address.lastName))
