                addressDTO.setState(Utils.removeControlCharacters(address.state))
                addressDTO.setPinCode(Utils.removeControlCharacters(address.pinCode))
                addressDTO.setPhone(Utils.removeControlCharacters(address.phone))
                addressDTO.setLandmark(Utils.removeControlCharacters(address.landmark))
                addressDTO.setDefaultAddress(address.defaultAddress)
                if (address.defaultAddress) {
                    addressDTO.setSelected(true)
                } else {
                    addressDTO.setSelected(false)
                }

                addressDTO.setArea(Utils.removeControlCharacters(address.area))
                addressDTO.setOtherArea(address.otherArea)
