                    userAddressInstance.setDefaultAddress(true)
                }
            }

            if (userAddressInstance.tin && UserAddressExtension.findByTinAndUserNotEqual(userAddressInstance.tin, user)) {
                userAddressInstance.errors.rejectValue("tin", "tin.duplicate.error")
                List states = locationService.fetchStatesList()
                List districts = locationService.fetchDistrictsList(userAddressInstance.state)
                List areas = locationService.fetchAreasList(userAddressInstance.state, userAddressInstance.city)
                List countries = [CountryCodesEnum.IN.name()]
                render(model: [cartItemListInstance: userCart, chequeBounceCharge: chequeBounceCharge, userCouponList: userCouponList, comboDiscount: comboDiscount,
