                return
            }
            Boolean invalidGST = false;
            String errorProperty = "gstin.duplicate.error";
            if (userAddressInstance.gstin && UserAddressExtension.findByGstinAndUserNotEqual(userAddressInstance.gstin, user)) {
                invalidGST = true
            }
            if (userAddressInstance.gstin && !invalidGST) {
                /*invalidGST=masterIndiaGstinConsumerService.validateGstin(webSite,userAddressInstance.gstin)
                errorProperty="gstin.invalid.error"*/
                def gstinValidationEnabled = appConfigParamService.enableGstinValidation(webSite);
                if (gstinValidationEnabled) {
                    def response = genericGstinService.validateGstin(webSite, gstin)
                    if (response.isSuccess() == false) {
                        invalidGST = true
                        errorProperty = message(code: 'gstin.invalid.error', default: 'Invalid Gstin')
                    }
                }
            }
            if (invalidGST) {
                userAddressInstance.errors.rejectValue("gstin", errorProperty)
                List states = locationService.fetchStatesList()
                List districts = locationService.fetchDistrictsList(userAddressInstance.state)
                List areas = locationService.fetchAreasList(userAddressInstance.state, userAddressInstance.city)
                List countries = [CountryCodesEnum.IN.name()]
                userAddressInstance.gstin = ""
