                               basketCount         : basketCount, userCoupon: userCoupon, deliveryCharges: surcharge, deliveryChargesText: deliveryChargesText, wholesaleRowTotal: wholesaleRowTotal,
                               wholesaleGrandTotal : wholesaleGrandTotal, cartItemCountInstance: cartItemCountInstance, userAddressInstance: userAddressInstance,
                               states              : states, districts: districts, comboDiscount: comboDiscount, areas: areas, countries: countries, userInstance: user, editFirmName: editFirmName, weekOff: weeklyOffList, tax: tax], view: 'editAddress')
                return
            }

            userAddressInstance.save(failOnError: true, flush: true)
            if (userAddressInstance.defaultAddress || !user.firstName || !user.company) {

                if (!user.firstName || userAddressInstance.defaultAddress) {
                    user.defaultPinCode = userAddressInstance.pinCode
                    user.firstName = userAddressInstance.firstName
                    user.lastName = userAddressInstance.lastName
                    user.pinCode = userAddressInstance.pinCode
                    user.fullName = userAddressInstance.lastName + " " + userAddressInstance.lastName ?: ""
                    locationService.setUserLocation(user)
                }
                if (!user.company) {
                    user.company = userAddressInstance.company
                }
                if (!user.gstin && userAddressInstance.gstin) {
                    user.gstin = userAddressInstance.gstin
                    user.company = userAddressInstance.company
                }
                user.save(flush: true)
                asyncCrmIntegrationService.userRegistration(user, webSite)
            } else if (!user.gstin && userAddressInstance.gstin) {
                user.gstin = userAddressInstance.gstin
                user.save(flush: true)
            }

            if (params['viewID'] == 'edit') {
                flash.message = message(code: 'account.updatedaddresssuccessfully.label')
            } else if (params['viewID'] == 'add') {
                flash.message = message(code: 'account.addedaddresssuccessfully.label')
            }

            if (cartId) {
                chain(controller: "checkout", action: "isCartChangeable", params: [id: userAddressInstance.id, cartId: cartId, addressId: params['addressId'], addressType: params['addressType']])
            } else {
                chain(controller: "checkout", action: "isCartChangeable", params: [id: userAddressInstance.id, addressId: params['addressId'], addressType: params['addressType']])
            }

            return

        }.invalidToken {
            flash.error = message(code: 'account.formexpired.label')
            if (cartId) {
                chain(controller: "checkout", action: "shipping", params: [id: cartId])
            } else {
                chain(controller: "checkout", action: "shipping")
            }
            return
        }
    }


