    @Secured(['ROLE_USER', 'ROLE_ADMIN', 'ROLE_MERCHANT'])
    def checkPreview(UserAddress userAddressInstance) {

        Map paramters = params
        def usr = springSecurityService.isLoggedIn() ? springSecurityService.currentUser : null
        User userExt = User.get(usr.id)
        String cartId = params['cartId']
        UserAddressExtension userAddress = userAddressInstance ? userAddressInstance : UserAddressExtension.get(userExt.addressIdSelected)
        if (null == userAddress) {
            flash.error = message(code: 'select.address.correctly')
            if (cartId) {
                chain(controller: "checkout", action: "shipping", params: [id: cartId])
                return
            } else {
                chain(controller: "checkout", action: "shipping")
                return
            }
        }
        String rsPaymentMethod = params['paymentOption']
        if (null == rsPaymentMethod) {
            chain(controller: "checkout", action: "paymentMethods", params: params)
            return
        }
        Map map = [:]
        map['walletAmount'] = params['redeem']
        map['paymentModeSelected'] = rsPaymentMethod
        checkoutService.saveUserModel(userExt, map);
        if (rsPaymentMethod.equals(PaymentMethodEnum.CASHONDELIVERY.toString())) {
            String webSite = request['x-website-id']
            List rsts = null
            Boolean isMobileAdvanceHoldCase = false
            if (userAddressInstance && usr) {
                rsts = userCartService.findUserCartList(usr, webSite, cartId, true)
                rsts.each { cart ->
                    UserCartExtension userCart = UserCartExtension.get(cart.id)
                    LakshyaMerchantProductOffer o = LakshyaMerchantProductOffer.get(userCart.offer.id)
                    String category = o.product.attributes['mastercategory']
                    isMobileAdvanceHoldCase = isMobileAdvanceHoldCase ? isMobileAdvanceHoldCase : category.equals("Mobiles")
                }
            }
            MasterCategory category = MasterCategory.findByMasterCategory("Mobiles")
            CategoryPayTMConfiguration payTM = CategoryPayTMConfiguration.findByCategoryAndPaymentMode(category, rsPaymentMethod)
            Double advanceAmount = payTM ? payTM.advAmount : 0
            SourcingServiceableLocation loc = SourcingServiceableLocation.findByPinCode(userAddressInstance.pinCode)
            Boolean skipAdvancePayment = loc ? true : false
            params['skippedAdvancePayment'] = skipAdvancePayment ? "Y" : "N";
            if (isMobileAdvanceHoldCase && (advanceAmount > 0) && !skipAdvancePayment) {
                chain(controller: "lakshyaCheckout", action: "advanceAmountCollection", id: userAddressInstance.id, params: params)
                return
            } else {
                chain(controller: "checkout", action: "preview", params: params)
                return
            }
        } else {
            chain(controller: "checkout", action: "preview", params: params)
            return
        }
    }

