            def cartWallets = walletBalanceMap['cartWallet']
            Double wAmt = creditNotes["normal"] ? new Double(creditNotes["normal"].toString()) : 0;
            cartWallets.each { k, amt ->
                wAmt += new Double(amt ? amt.toString() : "0").round(2);
            }
            walletAmount = Math.min(new Double(walletAmount.toString()), wAmt)
            if (rsts) {

                rsts.each {
                    index++

                    if (springSecurityService.isLoggedIn()) {
                        it.offer = catalogService.updateEstimatedDeliveryDays(it.offer, pinCode, webSite)
                    }
                    if (cartProductsName) {
                        cartProductsName += ("," + it.offer.product.attributes.name)
                    } else {
                        cartProductsName = it.offer.product.attributes.name
                    }

                    minimumOrderQty = it.offer.minimumOrderQty ? it.offer.minimumOrderQty : it.offer.merchant.minimumOrderQty
                    orderMultiples = it.offer.multiples ? it.offer.multiples : it.offer.merchant.multiples
                    if (it.offer.store) {

                        //Check serviceability

                        if (serviceableAddress) {
                            serviceableAddress = merchantServiceabilityService.checkAvailability(it.offer.merchant, pinCode)
                        }


                        if (it.offer.qty <= 0) {
                            anyItemOos = true
                        }
                        def cashBack = rt.instantcashbackamount(affiliateBidAbsolute: it.offer.storeBidAbsolute).toDouble()
                        storeRowTotal = storeRowTotal + ((it.offer.offerPrice - cashBack) * it.qty)
                        def regularDiscount = 0
                        if (it.offer.regularPrice && it.offer.offerPrice) {
                            regularDiscount = it.offer.regularPrice - it.offer.offerPrice
                        }
                        storeSavings = storeSavings + ((it.qty * cashBack) + (regularDiscount * it.qty))

                        store << g.render(template: "storecartitem", model: [cartItemInstance: it, storeI: storeI, anyItemOos: anyItemOos,
                                                                             minimumOrderQty : minimumOrderQty, orderMultiples: orderMultiples, cartId: cartId])
                        storeCartCount = storeCartCount + 1
                    }
                    if (it.offer.wholesale) {

                        //Check serviceability
                        if ((it.offer.productLead && it.offer.inventoryQty < it.qty) || !it.offer.active) {
                            inventoryOk = false
                            anyItemOos = true
                        } else if (it.offer.qty < it.qty || !it.offer.active) {
                            inventoryOk = false
                            anyItemOos = true
                        }
                        if (serviceableAddress) {
                            serviceableAddress = merchantServiceabilityService.checkAvailability(it.offer.merchant, pinCode)
                        }
                        def regularDiscount = 0
                        if (it.offer.regularPrice && it.offer.offerPrice) {
                            regularDiscount = it.offer.regularPrice - it.offer.offerPrice
                        }
                        wholesaleSavings = wholesaleSavings + (regularDiscount * it.qty)
                        wholesale << g.render(template: "/lakshyaCart/wholesalecartitem", model: [cartItemInstance : it, cartWallets: cartWallets,
                                                                                                  storeI           : wholesaleI, anyItemOos: anyItemOos, minimumOrderQty: minimumOrderQty, maximumOrderQty: it.offer.qty, orderMultiples: orderMultiples, cartId: cartId,
                                                                                                  actionPage       : "preview", addressId: userAddressInstance.id, index: index, advancePaymentMethod: params['paymentOptions'],
                                                                                                  advanceAmount    : params['advanceAmount'], redeem: params['redeem'], redeem1: params['redeem1'], paymentOption: params['paymentOption'],
                                                                                                  surchargeDiscount: params['surchargeDiscount'], skipAdvancePayment: params['skipAdvancePayment'], billingAddress: UserAddressExtension.get(params['billingAddress'])])
                        wholesaleRowTotal += (it.offer.offerPrice) * it.qty
                        wholesaleCartCount = wholesaleCartCount + 1
                        totalItems += it.qty
                    }
                    storeI = storeI + 1
                    wholesaleI = wholesaleI + 1
                }
                pResult['store'] = store
                pResult['wholesale'] = wholesale

            }

            def surcharge = 0
            def userCoupon
            def cartItemCountInstance = rsts ? rsts.size() : 0
            def bulkDiscount = 0
            def basketDiscount = 0
            def basketCount = 0
            def firstOrderDiscount
            def comboDiscount
            def userCouponList
            def chequeBounceCharge
            def deliveryChargesText
            def tax
            if (cartSummary) {
                deliveryChargesText = cartSummary.deliveryChargesText
                wholesaleRowTotal = cartSummary.total
                surcharge = cartSummary.deliveryCharges
                userCoupon = cartSummary.userCoupon
                bulkDiscount = cartSummary.bulkDiscount
                basketDiscount = cartSummary.basketDiscount
                basketCount = cartSummary.basketCount
                firstOrderDiscount = cartSummary.usrFirstOrderDiscount
                comboDiscount = cartSummary.comboDiscount
                userCouponList = cartSummary.userCouponList
                chequeBounceCharge = cartSummary.chequeBounceCharge
                tax = cartSummary["tax"]
            }
            def tagPoints = wholesaleRowTotal * tagRate
            tagPoints = tagPoints ? tagPoints.intValue() : 0

            def cartValidMap = lakshyaUtilsService.validateCartValue(rsts, webSite, wholesaleGrandTotal, session['paymentOption']);
            //coupon redirection
            def couponRedirect = [:]
            couponRedirect.controller = "lakshyaCheckout"
            couponRedirect.action = "preview"


            if (rsts.size() == 0) {
                redirect(controller: "lakshyaCart", action: "index")
                return
            }
            wholesaleGrandTotal = Math.round(wholesaleGrandTotal * 100.0) / 100.0
            if (session['paymentOption'] == "WALLET" && (walletBalance < wholesaleGrandTotal)) {
                flash.error = message(code: 'pay.walletinsufficientbalance.label')
                chain(controller: "lakshyaCheckout", action: "paymentMethods", id: userAddressInstance.id, params: [cartId: params?.cartId])
            } else if (session['paymentOption'] == "WALLET" && (wholesaleGrandTotal - Math.round(walletAmount * 100.0) / 100.0) != 0) {
                flash.error = message(code: 'preview.cartqtychanged.label')
                chain(controller: "lakshyaCheckout", action: "paymentMethods", id: userAddressInstance.id, params: [cartId: params?.cartId])
            } else if (walletAmount > wholesaleGrandTotal) {
                flash.error = message(code: 'preview.cartqtychanged.label')
                chain(controller: "lakshyaCheckout", action: "paymentMethods", id: userAddressInstance.id, params: [cartId: params?.cartId])
            }


            wholesaleGrandTotal = wholesaleGrandTotal - walletAmount
            def isElectricalOrder = true
            def cdcPDCCategories = servletContext.configuration."${request['x-website-id'].toString()}"."system_cdc_pdc_categories"
            List categoryList = cdcPDCCategories?.tokenize(",")
            cartValidMap.categories?.tokenize(",").each { category ->
                def isOrder = false;
                categoryList?.each { confCategory ->
                    if (confCategory.trim().equalsIgnoreCase(category)) {
                        isOrder = true;
                    }
                }
                isElectricalOrder = isElectricalOrder ? isOrder : isElectricalOrder
            }
            //Check CHEQUE limit if cart change at preview page
            if (session['paymentOption'] == PaymentMethodEnum.CHEQUE.toString() || session['paymentOption'] == PaymentMethodEnum.POSTDATEDCHEQUE.toString()) {
                def amt = lakshyaOrderService.getAdditionalDiscountSurchargeValue(wholesaleGrandTotal, session['paymentOption'], usr, cartId, webSite)
                if (!lakshyaOrderService.isChequeApplicable(webSite, usr, amt, isElectricalOrder)) {
                    flash.error = lakshyaOrderService.reasonForChequeUnavailability(webSite, usr, amt, isElectricalOrder)
                    chain(controller: "lakshyaCheckout", action: "paymentMethods", id: userAddressInstance.id, params: [cartId: params?.cartId])
                }
            }
            //Check COD limit if cart change at preview page
            if (session['paymentOption'] == PaymentMethodEnum.CASHONDELIVERY.toString()) {
                def amt = lakshyaOrderService.getAdditionalDiscountSurchargeValue(wholesaleGrandTotal, session['paymentOption'], usr, cartId, webSite)
                if (!lakshyaOrderService.isCODApplicable(webSite, usr, amt)) {
                    flash.error = lakshyaOrderService.reasonForCODUnavailability(webSite, usr, amt)
                    chain(controller: "lakshyaCheckout", action: "paymentMethods", id: userAddressInstance.id, params: [cartId: params?.cartId])
                }
            }

            if (session['paymentOption'] == PaymentMethodEnum.CREDIT.toString()) {
                def amt = lakshyaOrderService.getAdditionalDiscountSurchargeValue(wholesaleGrandTotal, session['paymentOption'], usr, cartId, webSite)
                def userBalance = lakshyaNBFCService.userBalance(usr, webSite, null, false, isElectricalOrder)
                if (userBalance < amt) {
                    def currencySymbol = servletContext.configuration."${webSite}"."default_currency_symbol"
                    flash.error = message(code: 'credit.orderAmountlimit.label', default: 'You can place order for amount {0} {1}', args: [currencySymbol, userBalance])
                    chain(controller: "lakshyaCheckout", action: "paymentMethods", id: userAddressInstance.id, params: [cartId: params?.cartId])
                }
            }


            def surchargeDiscount = lakshyaOrderService.getAdditionalDiscountSurchargeInfo(wholesaleGrandTotal, session['paymentOption'], usr, cartId, webSite)
            def finalAmount
            if (surchargeDiscount) {
                finalAmount = lakshyaOrderService.getAdditionalDiscountSurchargeValue(wholesaleGrandTotal, session['paymentOption'], usr, cartId, webSite)
            }

            if (userCoupon && wholesaleGrandTotal < 0) {
                wholesaleGrandTotal = wholesaleGrandTotal + userCoupon.discountAmount
                promotionService.removeAppliedCoupon(userCoupon)
                userCoupon = null
                flash.message = ""
                flash.error = message(code: 'coupon.payableamtinsufficientbalance.label')
            }

            if (params?.linkId) {
                def orderTrackingDetails = [:]
                orderTrackingDetails['linkId'] = params['linkId']
                orderTrackingDetails['usr'] = usr

                //start of hit clever tap
                def source = "Web"
                def cleverTapUrl = servletContext.configuration."${wst}"."clevertap_app_url"
                def cleverTapId = servletContext.configuration."${wst}"."clevertap_app_id"
                def cleverTapPassCode = servletContext.configuration."${wst}"."clevertap_app_passcode"
                //checkoutService.sendDataToCleverTap(orderTrackingDetails, cleverTapUrl, cleverTapId, cleverTapPassCode,source);
                //end of clever
            }
            //lakshyaCartService.removeCartTempDetails(usr.id?.toString(),cartId)
            def tempCartDetails = lakshyaCartService.updateCartTempDetails(cartId, usr.id.toString(), session['paymentOption'], userAddressInstance.id,
                    walletAmount, params['advanceAmount'], params['paymentOptions'], params['skippedAdvancePayment'])
            [chequeBounceCharge : chequeBounceCharge, cartWallets: cartWallets, userCouponList: userCouponList, comboDiscount: comboDiscount, user: usr,
             walletAmount       : tempCartDetails.wallet, paymentOption: tempCartDetails.selectedPaymentMethod, firstOrderDiscount: firstOrderDiscount,
             couponRedirect     : couponRedirect, activeProductCounts: basketCount, basketDiscount: basketDiscount, cartValidMap: cartValidMap,
             userAddressInstance: userAddressInstance, serviceableAddress: serviceableAddress, cartItemListInstance: rsts, cartItemCountInstance: rsts.size(),
             processedResult    : pResult, wholesaleGrandTotal: wholesaleGrandTotal, wholesaleRowTotal: wholesaleRowTotal, wholesaleSavings: wholesaleSavings,
             storeRowTotal      : storeRowTotal, storeSavings: storeSavings, tagPoints: tagPoints, anyItemOos: anyItemOos, deliveryChargesText: deliveryChargesText, deliveryCharges: surcharge,
             grandTotal         : wholesaleGrandTotal, userCoupon: userCoupon, cartId: cartId, bulkDiscount: bulkDiscount, showGstMsg: showGstMsg, totalItems: totalItems,
             surchargeDiscount  : surchargeDiscount, finalAmount: finalAmount, cartProductsName: cartProductsName, linkId: params['linkId'], advancePaymentMethod: params['paymentOptions'],
             advanceAmount      : params['advanceAmount'], redeem: params['redeem'], skipAdvancePayment: userExt.skipAdvancePayment, cartItemListInstance: rsts, billingAddress: UserAddressExtension.get(params['billingAddress']), tax: tax]
        }
    }

    @Secured(['ROLE_USER', 'ROLE_ADMIN', 'ROLE_MERCHANT'])
    def commit(UserAddress userAddressInstance) {
        preventCache(response)
        Boolean er = false, emptyCartFlag = false, errorJsonFlag = false
        def data = new Data()
        def rsPaymentMethod = params.rsPaymentMethod
        def usr = springSecurityService.isLoggedIn() ? springSecurityService.currentUser : null
        if (params.rsPaymentMethod != null && params.rsPaymentMethod == PaymentMethodEnum.RUPIFICREDIT.toString()) {
            try {
                def resData=[:]
                def isGSTINVerified = checkoutService.getGstinStatus(usr, userAddressInstance)
                resData.isGSTINVerified = isGSTINVerified
                data.data = resData
                if (isGSTINVerified == false) {
                    data.errors << [message(code: 'lakshyacheckout.gstin.null.label', default: 'Please add gstin to the default address for placing orders.')]
                    render data as JSON
                    return
                }
            }
            catch (Exception ex){
                ex.printStackTrace()
            }
        }
        if ("NETBANKING".equals(rsPaymentMethod) || "CREDIT_DEBIT".equals(rsPaymentMethod)) {
            errorJsonFlag = true
        }
        try {
            params['addressId'] = params['id']
            params['usrId'] = usr.id
            params['baseUrl'] = utilsService.extractHostName(request)
            Map responseMap
            def marketplace = session["marketplace"] ? session["marketplace"]?.toString() : null
            if(marketplace){
                params.clientId= marketplace
            }
            def dataMap=[:]
            def assistAgent = session['AssistAgent'] ? session['AssistAgent'] : null
            def isPromotionApplicable = true
            if(assistAgent){
                isPromotionApplicable = promotionService.isPromotionAllow(assistAgent)
            }
            dataMap.isPromotionApplicable = isPromotionApplicable
            Payment.withNewSession { sess ->
                responseMap = checkoutService.createOrder(params, request, response, session, PromotionPlatformEnum.WEB,dataMap)
            }
            if (responseMap['error']) {
                Map resMap = responseMap['error']
                if (resMap.msgArgs) {
                    flash.error = message(code: resMap.msgCode, args: resMap.msgArgs)
                    data.errors << message(code: resMap.msgCode, args: resMap.msgArgs)
                } else {
                    data.errors << message(code: resMap.msgCode)
                    flash.error = message(code: resMap.msgCode)
                }
                if (errorJsonFlag) {
                    render data as JSON
                } else {
                    chain(controller: resMap.controller, action: resMap.action, params: resMap['params'])
                }

            } else if (responseMap['success']) {
                Map resMap = responseMap['success']
                emptyCartFlag = resMap['emptyCartFlag']
                Payment payment = responseMap['payment']
                if (emptyCartFlag) {
                    notify('orderCreatedPaymentPending', ['payment': payment, 'webSite': request['x-website-id'].toString()])
                }
                if (resMap.msgArgs) {
                    flash.message = message(code: resMap.msgCode, args: resMap.msgArgs)
                } else {
                    flash.message = message(code: resMap.msgCode)
                }

                /*if("payU".equals(resMap.controller)){
                   redirect(url: "/razorpay/submit.json?masterOrderId=${payment.masterOrderId}&addressId="+params['addressId'])
                    //redirect(controller:"razorpayWeb",action:"submit", params:params)

                }else{*/

                if (params.rsPaymentMethod != null && params.rsPaymentMethod == "RUPIFICREDIT") {
                    try {

                        String paymentId = payment.id.toString()
                        RupifiPayment rupifiPayment = new RupifiPayment();
                        User user = User.get(usr.id)
                        rupifiPayment.setUser(user)
                        rupifiPayment.setMasterOrderId(payment.masterOrderId)
                        rupifiPayment.setStatus("PENDING")
                        rupifiPayment.setPaymentId(paymentId)
                        rupifiPayment.save(failOnError: true, flush: true)
                    }
                    catch (Exception e) {
                        e.printStackTrace()
                    }
                }

                parseParams(resMap['params'])
                //params.walletAmount = payment.walletAmount
                forward(controller: resMap.controller, action: resMap.action, id: resMap['id'])
                // }
            } else {
                if (errorJsonFlag) {
                    data.errors << message(code: 'lakshyacheckout.technicalproblem.label')
                    render data as JSON
                } else {
                    flash.error = message(code: 'lakshyacheckout.technicalproblem.label')
                    chain(controller: 'lakshyaCheckout', action: 'shipping', id: userAddressInstance.id)
                }
            }


        } catch (Exception oc) {
            log.error("Error in creating order and payment in checkout", oc)
            if (errorJsonFlag) {
                data.errors << message(code: 'lakshyacheckout.technicalproblem.label')
                render data as JSON
            } else {
                flash.error = message(code: 'lakshyacheckout.technicalproblem.label')
                chain(controller: 'lakshyaCheckout', action: 'shipping', id: userAddressInstance.id)
            }
        }

        if (er) {
            //Handle error response
            response.status = 500
            render ""
            return
        } else {
            //Handle success response
            return
        }
        response.status = 500
        render ""
        return
    }

    def parseParams(def resmaParams) {
        def splitValue
        try {
            resmaParams.each { v ->
                String value = v
                splitValue = value.split("=")
                if (splitValue.size() > 1 && splitValue[0] && splitValue[1] && !params.containsKey(splitValue[0])) {
                    params[splitValue[0]] = splitValue[1]
                }
            }
        } catch (Exception e) {
            e.printStackTrace()
        }
    }

    @Secured(['ROLE_USER', 'ROLE_ADMIN', 'ROLE_MERCHANT'])
    def advanceAmountCollection(UserAddress userAddressInstance) {
        String cartId = params['cartId']
        String webSite = request['x-website-id']
        def usr = springSecurityService.isLoggedIn() ? springSecurityService.currentUser : null
        MasterCategory category = MasterCategory.findByMasterCategory("Mobiles")
        CategoryPayTMConfiguration payTM = CategoryPayTMConfiguration.findByCategoryAndPaymentMode(category, PaymentMethodEnum.CASHONDELIVERY.toString())
