    /**
     * @param paymentInstance
     * @return
     */
    private def removeFromCustomerCart(Payment paymentInstance) {

        def userCouponList = UserCoupon.findAllByPayment(paymentInstance);
        if (userCouponList) {
            userCouponList.each { userCoupon ->
                if (userCoupon) {
                    promotionService.updateRedeemedUserCouponStatus(userCoupon)
                }
            }
        }

        def cartList

        if (paymentInstance.cartId) {
            cartList = UserCart.findAllByUserAndCartId(paymentInstance.rqUser, paymentInstance.cartId);
        } else {
            cartList = UserCart.findAllByUserAndCartIdIsNull(paymentInstance.rqUser);
        }
        try{
            List<AbandonedCartDetails> abandonedCartDetails = AbandonedCartDetails.createCriteria().list() {
                eq('user',paymentInstance?.rqUser?.id)
                'in'('carts',cartList)
            }
            abandonedCartDetails.each { abc ->
                abc?.delete(flush: true, failOnError: true)
            }
        }catch(Exception e){
            e.printStackTrace()
        }
        cartList.each {
            it?.delete(flush: true, failOnError: true)
        }
    }


