                            getAdditionalDiscountSurchargeInfo(wholesaleGrandTotal+loyaltyDiscount, methodNm, allowedMethodMap, usr, cartId, isElectricalOrder, walletAppliedAmnt, isWalletSelected,cartValidMap)
                        } catch (Exception e) {
                            e.printStackTrace()
                        }
                        allowedMethods << allowedMethodMap

                        //Add additional method CARDONDELIVERY as per LIPLWEB-6445
                        allowedMethodMap = [:]
                        allowedMethodMap.name = 'CARDONDELIVERY'
                        allowedMethodMap.title = message(code: "payment.method.title.cardondelivery")
                        try {
                            loyaltyDiscount = (loyaltyDiscount && loyaltyDiscount>0)?loyaltyDiscount:0
                            getAdditionalDiscountSurchargeInfo(wholesaleGrandTotal+loyaltyDiscount, methodNm, allowedMethodMap, usr, cartId, isElectricalOrder, walletAppliedAmnt, isWalletSelected,cartValidMap)
                        } catch (Exception e) {
                            e.printStackTrace()
                        }

                        allowedMethods << allowedMethodMap

                    } else if (methodName.equals(PaymentMethodEnum.RUPIFICREDIT)) {
                        allowedMethodMap.name = methodNm
                        allowedMethodMap.title = message(code: "title.rupifi")
                        allowedMethodMap.lowBalanceMsg = message(code: "rupifi.low.balance.msg")

                        try {
                            loyaltyDiscount = (loyaltyDiscount && loyaltyDiscount>0)?loyaltyDiscount:0
                            getAdditionalDiscountSurchargeInfo(wholesaleGrandTotal+loyaltyDiscount, methodNm, allowedMethodMap, usr, cartId, isElectricalOrder, walletAppliedAmnt, isWalletSelected,cartValidMap)
                        } catch (Exception e) {
                            e.printStackTrace()
                        }
                        allowedMethods << allowedMethodMap
                    } else {

                        allowedMethodMap.name = methodNm
                        allowedMethodMap.title = message(code: "payment.method.title.${methodNm.toString().toLowerCase()}")

                        if (methodName.equals(PaymentMethodEnum.NEFTRTGS)) {
                            allowedMethodMap.paymentDetails = getBankDetails("NEFT")
                        }
                        try {
                            loyaltyDiscount = (loyaltyDiscount && loyaltyDiscount>0)?loyaltyDiscount:0
                            getAdditionalDiscountSurchargeInfo(wholesaleGrandTotal+loyaltyDiscount, methodNm, allowedMethodMap, usr, cartId, isElectricalOrder, walletAppliedAmnt, isWalletSelected,cartValidMap)
                        } catch (Exception e) {
                            e.printStackTrace()
                        }
                        allowedMethods << allowedMethodMap
                    }
                }
            }
            def paymentMethods = [];

            allowedMethods.each {
                method ->
                    def methodName = method.name;
                    if(marketplace == null || marketplace==MarketplaceEnum.LTD.toString()){
                        paymentMethods << method
                    }else{
                        def mProperties = lakshyaUtilsService.getMarketplaceProperties(clientId)
                        if(mProperties && mProperties?.paymentMethod){
                            def payementoptions = mProperties.paymentMethod
                            if(payementoptions.contains(methodName)){
                                paymentMethods << method
                            }
                        }else{
                            paymentMethods << method
                        }
                    }
            }
            data.data.paymentmethods = paymentMethods

            /*if(merchantTotalCreditAmount){
                data.data.creditBalance = Utils.setDecimalFormat(merchantTotalCreditAmount)
            }*/

            data.data.wholesaleGrandTotal = Utils.setDecimalFormat(wholesaleGrandTotal)

            def dataValue = walletService.checkWalletValues(data)
            data.data.applicableCreditNoteData = dataValue.get("applicableCreditNote")
            data.data.normalWalletBalanceData = dataValue.get("normalWalletBalance")
            data.data.applicableWalletBalanceData = dataValue.get("applicableWalletBalance")
            data.data.nonRestrictedBrandValueData = dataValue.get("nonRestrictedBrandValue")
            data.data.reducedWalletBalanceData = dataValue.get("reducedWalletBalance")
            data.data.walletBalanceAppliedData = dataValue.get("walletBalanceApplied")
            data.data.canUseWalletAmountData = dataValue.get("canUseWalletAmount")
            data.data.walletPropData = dataValue.get("walletProp")
            data.data.isGstinVerified = checkoutService.getGstinStatus(usr,userAddressInstance)

            data.setStatusCode(HttpStatus.OK)

            respond data
            return
        }
    }

