    private def getCartValidPaymentMap(def rsts, String webSite, Double wholesaleGrandTotal) {
        def cartValidPaymentsMap = [:]
        def allowedPaymentMethods = servletContext.configuration."${request['x-website-id'].toString()}"."consolidated_payment_methods_allowed"
        allowedPaymentMethods.tokenize(",").each { paymentMethod ->
            def cartValidPaymentMap = lakshyaUtilsService.validateCartValue(rsts, webSite, wholesaleGrandTotal, paymentMethod.toString());
            String paymentSummary = null
            if (cartValidPaymentMap['minimumCartFlag']) {
                cartValidPaymentMap['categoryList'].each { category ->
                    if (paymentSummary) {
                        paymentSummary += "\n" + category['categoryName']
                    } else {
                        paymentSummary = category['categoryName']
                    }
                    if (category['minMax'] == 'Min') {
                        paymentSummary += message(code: 'shoppingcart.categoryMinCartitem.label',
                                default: " category items must have value greater than or equal to ")
                        paymentSummary += " " + category['minimumCartValue']
                    } else {
                        paymentSummary += message(code: 'shoppingcart.categoryMaxCartitem.label',
                                default: " category items must have value less than or equal to ")
                        paymentSummary += " " + category['maximumCartValue']
                    }
                    paymentSummary += " for " + paymentMethod + " Payment Mode"
                }
            }
            cartValidPaymentsMap[paymentMethod.toString()] = paymentSummary
        }

        cartValidPaymentsMap
    }

    def mobAdvanceAmountCollection(params) {
        def addressId = request.JSON.addressId
        params['cartId'] = request.JSON.cartId
        def wallet = request.JSON.redeemedAmount
        params['requestType'] = "API"
        UserAddress userAddressInstance = UserAddressExtension.get(addressId)
        def amountdetails = advanceAmountCollection(userAddressInstance)
        def data = new Data()
        def methods = []

        boolean isCCDC = true
        def errors = amountdetails?.errors
        if (amountdetails && !errors) {
            amountdetails?.paymentMethods.each { ad ->
                def pymntMethod = ad?.toString()?.toLowerCase()
                def methodMap = [:]
                if ("paytm".equals(pymntMethod)) {
                    methodMap.title = "PAYTM"
                    methodMap.navigationArea = "PAYTM"
                    methodMap.active = true
                    methods << methodMap
                }
                if ("netbanking".equals(pymntMethod)) {
                    methodMap = [:]
                    methodMap.title = "Netbanking"
                    methodMap.navigationArea = "NET_BANKING"
                    methodMap.active = true
                    methods << methodMap
                }

                if ("creditcard".equals(pymntMethod) || "debitcard".equals(pymntMethod) && isCCDC) {
                    isCCDC = false
                    methodMap = [:]
                    methodMap.title = "Credit/Debit Card"
                    methodMap.navigationArea = "CC_DC"
                    methodMap.active = true
                    methods << methodMap
                }
            }
            def advanceAmount = amountdetails.advanceAmount ? amountdetails.advanceAmount : 0
            def additionalAmount = amountdetails.additionalAmount ? amountdetails.additionalAmount : 0
            def grossTotal = amountdetails.wholesaleRowTotal
            def discount = 0
            def grandTotal = amountdetails.wholesaleGrandTotal - advanceAmount - additionalAmount
            def surcharge = amountdetails.surchargeDiscount ? amountdetails.surchargeDiscount : 0
            def deliveryCharges = amountdetails.deliveryCharges ? amountdetails.deliveryCharges : 0
            def userCouponList = amountdetails.userCouponList
            def basketDiscount = amountdetails.basketDiscount
            def comboDiscount = amountdetails.comboDiscount
            def summaryMap = [:]
            if (wallet && wallet > 0) {
                grandTotal = grandTotal - wallet
                params['redeem'] = wallet
                if (grandTotal < 0) {
                    wallet = wallet + grandTotal
                    grandTotal = 0
                }
                summaryMap.redeemedAmount = wallet

            }
            def paymentSummary = []
            summaryMap.advanceAmount = Utils.setScale(advanceAmount)
            summaryMap.subTotal = Utils.setScale(grossTotal)
            summaryMap.grandTotal = Utils.setScale(grandTotal)
            summaryMap.additionalDiscount = Utils.setScale(additionalAmount)
            summaryMap.deliveryCharges = Utils.setScale(deliveryCharges)
            summaryMap.surcharge = Utils.setScale(surcharge)

            def allCharges = []
            def chargeMap = [:]
            if (deliveryCharges) {
                chargeMap.value = Utils.setScale(deliveryCharges)
                chargeMap.name = "Delivery Charges"
                allCharges << chargeMap
            }
            def allDiscount = [:]
            def allDiscounts = []
            if (additionalAmount) {
                allDiscount.name = "Additional Discount (-) "
                allDiscount.value = Utils.setScale(additionalAmount)
                allDiscounts << allDiscount
            }
            if (basketDiscount) {
                allDiscount.name = "Basket Discount (-) "
                allDiscount.value = Utils.setScale(basketDiscount)
                allDiscounts << allDiscount
            }
            if (comboDiscount) {
                allDiscount = [:]
                allDiscount.name = "Combo Discount (-) "
                allDiscount.value = Utils.setScale(comboDiscount)
                allDiscounts << allDiscount
            }

            userCouponList?.each { ucl ->
                allDiscount = [:]
                allDiscount.name = ucl.coupon?.promotion?.promotionName + " (-) "
                allDiscount.value = Utils.setScale(ucl.discountAmount)
                allDiscounts << allDiscount
            }
            summaryMap.allDiscounts = allDiscounts
            summaryMap.allCharges = allCharges

            paymentSummary << summaryMap
            def messages = []
            def appversion = request.getHeader("version") ? request.getHeader("version").toString() : "0"
            int appver = Integer.parseInt(appversion)
            if (appver < 35) {
                messages << message(code: 'pay.advance.payment.message', args: [amountdetails.default_currency_symbol, advanceAmount])
            } else {
                messages << message(code: 'pay.advance.payment.desc', args: [amountdetails.default_currency_symbol, advanceAmount])
            }
            data.data = [paymentMethods: methods, paymentSummary: summaryMap, messages: messages]
            data.setStatusCode(HttpStatus.OK)
        } else {
            data.setStatusCode(HttpStatus.NOT_FOUND)
        }
        respond data
        return
    }

    @Secured(['ROLE_USER', 'ROLE_ADMIN', 'ROLE_MERCHANT'])
    def isCartChangeable(UserAddress userAddressInstance) {
        if (params['addressType']) {
            if (params['addressType'] == "billing") {
                chain(controller: "checkout", action: "paymentMethods", params: params);
                return;
            }
        }

        def cartId = params['cartId']
        User usr = springSecurityService.isLoggedIn() ? springSecurityService.currentUser : null
        def webSite = request['x-website-id'] ? request['x-website-id'].toString() : null
        def rsts = userCartService.findUserCartList(usr, webSite, cartId, true)

        //Check serviceability of selected address
        def serviceableAddress = true
        def isCartChangeable = false
        def pinCode = userAddressInstance?.pinCode
        def oosProducts = [];
        if (rsts) {
            rsts?.each {
                if (serviceableAddress) {
                    serviceableAddress = merchantServiceabilityService.checkAvailability(it.offer.merchant, pinCode)
                }

                if (!serviceableAddress) {
                    //LIPLWEB-6044 Case when Buyer browsed the products using Default Pin Code,
                    //but during checkout selected an address other than the default pincode
                    //if (!usr.defaultPinCode.equals(userAddressInstance.pinCode)) {
                    def alternateOffer = offerAdapterService.updateOfferBasedOnAddress(usr.id.toString(), userAddressInstance.id.toString(), it.id.toString());
                    if (alternateOffer) {
                        serviceableAddress = true;
                        isCartChangeable = true;
                    }
                    //}
                }

                if (!serviceableAddress) {
                    String prodName = it?.offer?.product?.attributes?.name
                    oosProducts << prodName;
                }
            }
        }
        params['isCartChanged'] = isCartChangeable;
        def serviceableFlag = 1
        if (!serviceableAddress) {
            serviceableFlag = 0
            if (cartId) {
                chain(controller: "checkout", action: "shipping", params: [id: cartId, serviceableFlag: serviceableFlag, oosProducts: oosProducts])
            } else {
                chain(controller: "checkout", action: "shipping", params: [serviceableFlag: serviceableFlag, oosProducts: oosProducts])
            }
        } else {
            chain(controller: "checkout", action: "paymentMethods", params: params)
        }
    }

