    private def modifyWalletForRestrictedBrands(def cartValidMap, def webSite, def data){
        Double restrictedBrandValue = cartValidMap.restrictedBrandValue
        def isRestrictedBrand = false
        TreeSet restrictedBrand = appConfigParamService.getRestrictedBrand(webSite)
        TreeSet productBrand = cartValidMap.productBrand
        if(restrictedBrand) {
            isRestrictedBrand = productBrand.equals(restrictedBrand)
            if(isRestrictedBrand){
            } else{
                for(String x : productBrand) {
                    if(restrictedBrand.contains(x)) {
                        isRestrictedBrand=true
                    }else{
                        isRestrictedBrand=false
                        break
                    }
                }
            }
        }
        def anyBrandRestricted
        productBrand.each{ br ->
            if(restrictedBrand.contains(br)){
                anyBrandRestricted = true;
            }
